//! Parsing of signals and wait target states.

use std::fmt;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct VariantNotFound;

impl fmt::Display for VariantNotFound {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "Matching variant not found")
    }
}

impl std::error::Error for VariantNotFound {}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Signal {
    SigKill,
    SigInt,
    SigTerm,
    SigCont,
    SigStop,
}

impl Signal {
    pub fn name(&self) -> &'static str {
        match self {
            Signal::SigKill => "SigKill",
            Signal::SigInt => "SigInt",
            Signal::SigTerm => "SigTerm",
            Signal::SigCont => "SigCont",
            Signal::SigStop => "SigStop",
        }
    }
}

pub fn parse_signal(input: &str) -> Result<Signal, VariantNotFound> {
    let lower = input.to_ascii_lowercase();
    let signal = match lower.as_str() {
        "sigkill" | "kill" | "9" => Signal::SigKill,
        "sigint" | "int" | "2" => Signal::SigInt,
        "sigterm" | "term" | "15" => Signal::SigTerm,
        "sigcont" | "cont" | "18" => Signal::SigCont,
        "sigstop" | "stop" | "19" => Signal::SigStop,
        _ => return Err(VariantNotFound),
    };
    Ok(signal)
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum WaitTargetStatus {
    Queued,
    Running,
    Done,
    Success,
}

impl WaitTargetStatus {
    pub fn name(&self) -> &'static str {
        match self {
            WaitTargetStatus::Queued => "Queued",
            WaitTargetStatus::Running => "Running",
            WaitTargetStatus::Done => "Done",
            WaitTargetStatus::Success => "Success",
