        "running" | "Running" => WaitTargetStatus::Running,
        "done" | "Done" => WaitTargetStatus::Done,
        "success" | "Success" => WaitTargetStatus::Success,
        _ => return Err(VariantNotFound),
    };
    Ok(status)
}
