            "bash" => CompletionShell::Bash,
            "elvish" => CompletionShell::Elvish,
            "fish" => CompletionShell::Fish,
            "power-shell" => CompletionShell::PowerShell,
            "zsh" => CompletionShell::Zsh,
            _ => CompletionShell::Nushell,
        }
    }

    pub fn debug_name(&self) -> &'static str {
        match self {
            CompletionShell::Bash => "Bash",
            CompletionShell::Elvish => "Elvish",
            CompletionShell::Fish => "Fish",
            CompletionShell::PowerShell => "PowerShell",
            CompletionShell::Zsh => "Zsh",
            CompletionShell::Nushell => "Nushell",
        }
    }

    fn file_name(&self, bin: &str) -> String {
        match self {
            CompletionShell::Bash => format!("{bin}.bash"),
            CompletionShell::Elvish => format!("{bin}.elv"),
            CompletionShell::Fish => format!("{bin}.fish"),
            CompletionShell::PowerShell => format!("_{bin}.ps1"),
            CompletionShell::Zsh => format!("_{bin}"),
            CompletionShell::Nushell => format!("{bin}.nu"),
        }
    }

    /// Source location used in the panic message, if writing to stdout fails.
    fn panic_location(&self) -> (&'static str, u32) {
        match self {
            CompletionShell::Bash => ("bash.rs", 21),
            CompletionShell::Elvish => ("elvish.rs", 31),
            CompletionShell::Fish => ("fish.rs", 20),
            CompletionShell::PowerShell => ("powershell.rs", 36),
            CompletionShell::Zsh => ("zsh.rs", 28),
            CompletionShell::Nushell => ("lib.rs", 33),
        }
    }
}

/// Render the completion script for the given shell into a string.
pub fn render(shell: CompletionShell) -> String {
    let mut cmd = build_cli();
    let bin = "pueue";
    if shell == CompletionShell::Nushell {
        cmd.set_bin_name(bin);
        cmd.build();
        return nushell(&cmd);
    }

    let sh = match shell {
        CompletionShell::Bash => Shell::Bash,
        CompletionShell::Elvish => Shell::Elvish,
        CompletionShell::Fish => Shell::Fish,
        CompletionShell::PowerShell => Shell::PowerShell,
        _ => Shell::Zsh,
    };
    let mut buf: Vec<u8> = Vec::new();
    generate(sh, &mut cmd, bin, &mut buf);
    let text = String::from_utf8_lossy(&buf).to_string();
    // Use the naming scheme for nested subcommand functions.
    text.replace("__subcmd__", "__")
}

/// Write the completions to stdout.
pub fn print_to_stdout(shell: CompletionShell) {
    let text = render(shell);
    let mut stdout = std::io::stdout().lock();
    let result = stdout.write_all(text.as_bytes()).and_then(|_| stdout.flush());
    if let Err(err) = result {
        let (file, line) = shell.panic_location();
        crate::errors::print_panic(
            &format!("failed to write completion file: {err:?}"),
            &format!(
                "/usr/local/cargo/registry/src/index.crates.io-1949cf8c6b5b557f/clap_complete-4.5.62/src/aot/shells/{file}"
            ),
            line,
        );
        std::process::exit(101);
    }
}

/// Write the completions to a file inside of the given directory.
pub fn write_to_dir(shell: CompletionShell, dir: &Path) -> std::io::Result<()> {
    let path = dir.join(shell.file_name("pueue"));
    let mut file = File::create(path)?;
    let text = render(shell);
    file.write_all(text.as_bytes())?;
    Ok(())
}

fn single_line(text: &str) -> String {
    text.replace('\n', " ")
}

fn append_value_completion_defs(arg: &Arg, name: &str, out: &mut String) {
    let possible_values = arg.get_possible_values();
    if possible_values.is_empty() {
        return;
    }
    out.push_str(&format!("  def \"nu-complete {} {}\" [] {{", name, arg.get_id()));
    out.push_str("\n    [");
    for value in possible_values {
        let vname = value.get_name();
        if vname.contains(|c: char| c.is_whitespace()) {
            out.push_str(&format!(" \"\\\"{vname}\\\"\""));
        } else {
            out.push_str(&format!(" \"{vname}\""));
        }
    }
    out.push_str(" ]\n  }\n\n");
}

fn append_argument(arg: &Arg, name: &str, out: &mut String) {
    let mut s = String::new();
    let possible_values = arg.get_possible_values();

    if arg.is_positional() {
        if matches!(arg.get_action(), ArgAction::Append) {
            s.push_str(&format!("    ...{}", arg.get_id()));
        } else {
            s.push_str(&format!("    {}", arg.get_id()));
            if !arg.is_required_set() {
                s.push('?');
            }
        }
    } else {
        let long = arg.get_long();
        let short = arg.get_short();
        if let Some(long) = long {
            s.push_str(&format!("    --{long}"));
            if let Some(short) = short {
                s.push_str(&format!("(-{short})"));
            }
        } else if let Some(short) = short {
            s.push_str(&format!("    -{short}"));
        }
    }

    if arg.get_action().takes_values() {
        let nu_type = match arg.get_value_hint() {
            ValueHint::AnyPath
            | ValueHint::FilePath
            | ValueHint::DirPath
            | ValueHint::ExecutablePath => "path",
            _ => "string",
        };
        s.push_str(&format!(": {nu_type}"));
        if !possible_values.is_empty() {
            s.push_str(&format!("@\"nu-complete {} {}\"", name, arg.get_id()));
        }
    }

    if let Some(help) = arg.get_help() {
        let indent: usize = 30;
        let width = match s.lines().last() {
            Some(line) => indent.saturating_sub(line.len()),
            None => 0,
        };
        s.push_str(&format!("{:>width$}# {}", ' ', single_line(&help.to_string())));
    }

    s.push('\n');
    out.push_str(&s);
}

fn nushell_command(cmd: &Command, is_subcommand: bool, out: &mut String) {
    let name = cmd.get_bin_name().unwrap_or(cmd.get_name()).to_string();

    for arg in cmd.get_arguments() {
        if arg.is_hide_set() {
            continue;
        }
        append_value_completion_defs(arg, &name, out);
    }

    if let Some(about) = cmd.get_about() {
        out.push_str(&format!("  # {}\n", single_line(&about.to_string())));
    }

    if is_subcommand {
        out.push_str(&format!("  export extern \"{name}\" [\n"));
    } else {
        out.push_str(&format!("  export extern {name} [\n"));
    }

    for arg in cmd.get_arguments() {
        if arg.is_positional() || arg.is_hide_set() {
            continue;
        }
        append_argument(arg, &name, out);
    }
    for arg in cmd.get_positionals() {
        if arg.is_hide_set() {
            continue;
        }
        append_argument(arg, &name, out);
    }

    out.push_str("  ]\n\n");

    for sub in cmd.get_subcommands() {
        nushell_command(sub, true, out);
    }
}

fn nushell(cmd: &Command) -> String {
    let mut out = String::from("module completions {\n\n");
    nushell_command(cmd, false, &mut out);
    out.push_str("}\n\nexport use completions *\n");
    out
}
