//! Error reporting that mimics the look of the original error handler.

use std::fmt;

/// An error report with a chain of messages and the location at which it was created.
#[derive(Debug, Clone)]
pub struct Report {
    /// Outermost message first.
    pub chain: Vec<String>,
    pub file: String,
    pub line: u32,
}

impl Report {
    pub fn new(msg: impl Into<String>, file: &str, line: u32) -> Report {
        Report {
            chain: vec![msg.into()],
            file: file.to_string(),
            line,
        }
    }

    /// Add context to an existing report.
    pub fn wrap(mut self, msg: impl Into<String>) -> Report {
        self.chain.insert(0, msg.into());
        self
    }

    /// Add context and update the location.
    pub fn wrap_at(mut self, msg: impl Into<String>, file: &str, line: u32) -> Report {
        self.chain.insert(0, msg.into());
        self.file = file.to_string();
        self.line = line;
        self
    }

    pub fn at(mut self, file: &str, line: u32) -> Report {
        self.file = file.to_string();
        self.line = line;
        self
    }
}

impl fmt::Display for Report {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.chain.join(": "))
    }
}

pub type Result<T> = std::result::Result<T, Report>;

/// Shorthand to create a report at a given location.
#[macro_export]
macro_rules! report {
    ($file:expr, $line:expr, $($arg:tt)*) => {
        $crate::errors::Report::new(format!($($arg)*), $file, $line)
