    "%Y-%m-%d\n%H:%M:%S".to_string()
}

fn default_callback_log_lines() -> usize {
    10
}

/// Errors that can happen while handling the configuration.
#[derive(Debug)]
pub enum SettingsError {
    IoPath(PathBuf, &'static str, std::io::Error),
    Deserialization(String),
}

impl std::fmt::Display for SettingsError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            SettingsError::IoPath(path, msg, err) => {
                write!(f, "I/O error at path {path:?} while {msg}:\n{err}")
            }
            SettingsError::Deserialization(msg) => {
                write!(f, "Error while reading configuration:\n{msg}")
            }
        }
    }
}

/// Expand a leading `~` to the home directory of the current user.
pub fn expand_home(old_path: &Path) -> PathBuf {
    if old_path.starts_with("~") {
        let home = dirs::home_dir();
        let path = old_path.to_string_lossy();
        let replaced = path.replacen('~', &home.to_string_lossy(), 1);
        return PathBuf::from(replaced);
    }
    old_path.to_path_buf()
}

impl Shared {
    pub fn pueue_directory(&self) -> PathBuf {
        if let Some(path) = &self.pueue_directory {
            expand_home(path)
        } else {
            dirs::data_dir().join("pueue")
        }
    }

    pub fn runtime_directory(&self) -> PathBuf {
        if let Some(path) = &self.runtime_directory {
            expand_home(path)
        } else if let Some(path) = dirs::runtime_dir() {
            path
        } else {
            self.pueue_directory()
        }
    }

    pub fn unix_socket_path(&self) -> PathBuf {
        if let Some(path) = &self.unix_socket_path {
            expand_home(path)
        } else {
            self.runtime_directory()
                .join(format!("pueue_{}.socket", dirs::username()))
        }
    }

    pub fn alias_file(&self) -> PathBuf {
        if let Some(path) = &self.alias_file {
            expand_home(path)
        } else {
            dirs::config_dir().join("pueue").join("pueue_aliases.yml")
        }
    }

    pub fn daemon_cert(&self) -> PathBuf {
        if let Some(path) = &self.daemon_cert {
            expand_home(path)
        } else {
            self.pueue_directory().join("certs").join("daemon.cert")
        }
    }

    pub fn shared_secret_path(&self) -> PathBuf {
        if let Some(path) = &self.shared_secret_path {
            expand_home(path)
        } else {
            self.pueue_directory().join("shared_secret")
        }
    }
}

fn parse_file(path: &Path, open_msg: &'static str) -> Result<Settings, SettingsError> {
    let file =
        File::open(path).map_err(|err| SettingsError::IoPath(path.to_path_buf(), open_msg, err))?;
    let reader = BufReader::new(file);
    serde_yaml::from_reader(reader).map_err(|err| SettingsError::Deserialization(err.to_string()))
}

impl Settings {
    /// Read the settings. Returns the settings and whether a config file has been found.
    pub fn read(from_file: &Option<PathBuf>) -> Result<(Settings, bool), SettingsError> {
        let from_file = from_file
            .clone()
            .or_else(|| std::env::var_os("PUEUE_CONFIG_PATH").map(PathBuf::from));

        if let Some(path) = &from_file {
            let settings = parse_file(path, "opening config file")?;
            return Ok((settings, true));
        }

        info!("pueue_lib::settings", "Parsing config files");

        let directories = vec![dirs::config_dir().join("pueue"), PathBuf::from(".")];
        for directory in directories {
            let path = directory.join("pueue.yml");
            info!("pueue_lib::settings", "Checking path: {path:?}");
            if path.exists() && path.is_file() {
                info!("pueue_lib::settings", "Found config file at: {path:?}");
                let settings = parse_file(&path, "opening config file.")?;
                return Ok((settings, true));
            }
        }

        info!("pueue_lib::settings", "No config file found. Use default config.");
        Ok((Settings::default(), false))
    }

    pub fn load_profile(&mut self, profile: &str) -> Result<(), SettingsError> {
        let nested = self.profiles.remove(profile).ok_or_else(|| {
            SettingsError::Deserialization(format!("Couldn't find profile with name \"{profile}\""))
        })?;
        self.client = nested.client;
        self.daemon = nested.daemon;
        self.shared = nested.shared;
        Ok(())
    }
}
