cat > src/dirs.rs <<'EOF'
//! Lookup of user specific directories.

use std::ffi::CStr;
use std::path::PathBuf;

fn passwd_entry() -> Option<(String, PathBuf)> {
    unsafe {
        let uid = libc::geteuid();
        let mut buf = vec![0 as libc::c_char; 16384];
        let mut pwd: libc::passwd = std::mem::zeroed();
        let mut result: *mut libc::passwd = std::ptr::null_mut();
        let rc = libc::getpwuid_r(uid, &mut pwd, buf.as_mut_ptr(), buf.len(), &mut result);
        if rc != 0 || result.is_null() {
            return None;
        }
        let name = CStr::from_ptr(pwd.pw_name).to_string_lossy().to_string();
        let dir = CStr::from_ptr(pwd.pw_dir).to_string_lossy().to_string();
        Some((name, PathBuf::from(dir)))
    }
}

pub fn home_dir() -> PathBuf {
    if let Some(home) = std::env::var_os("HOME") {
        if !home.is_empty() {
            return PathBuf::from(home);
        }
    }
    passwd_entry().map(|(_, dir)| dir).unwrap_or_default()
}

fn absolute_env(name: &str) -> Option<PathBuf> {
    let value = std::env::var_os(name)?;
    let path = PathBuf::from(value);
    if path.is_absolute() {
        Some(path)
    } else {
        None
    }
}

pub fn data_dir() -> PathBuf {
    absolute_env("XDG_DATA_HOME").unwrap_or_else(|| home_dir().join(".local/share"))
}

pub fn config_dir() -> PathBuf {
    absolute_env("XDG_CONFIG_HOME").unwrap_or_else(|| home_dir().join(".config"))
}

pub fn runtime_dir() -> Option<PathBuf> {
    absolute_env("XDG_RUNTIME_DIR")
}

pub fn username() -> String {
    passwd_entry().map(|(name, _)| name).unwrap_or_default()
}
EOF"}

