use std::io::Write;
use std::sync::atomic::{AtomicU8, Ordering};

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Debug)]
pub enum Level {
    Error = 1,
    Warn = 2,
    Info = 3,
    Debug = 4,
    Trace = 5,
}

static MAX_LEVEL: AtomicU8 = AtomicU8::new(2);

pub fn init(verbosity: u8) {
    let level = match verbosity {
        0 => Level::Warn,
        1 => Level::Info,
        2 => Level::Debug,
        _ => Level::Trace,
    };
    MAX_LEVEL.store(level as u8, Ordering::SeqCst);
}

pub fn enabled(level: Level) -> bool {
    (level as u8) <= MAX_LEVEL.load(Ordering::SeqCst)
}

fn ansi_enabled() -> bool {
    match std::env::var("NO_COLOR") {
        Ok(value) => value.is_empty(),
        Err(_) => true,
    }
}

/// Write a log line. `fields` are rendered behind the message as `name=value`.
pub fn write(level: Level, target: &str, message: &str, fields: &[(&str, String)]) {
    if !enabled(level) {
        return;
    }
    let time = chrono::Local::now().format("%H:%M:%S").to_string();
    let (name, color) = match level {
        Level::Error => ("ERROR", "31"),
        Level::Warn => (" WARN", "33"),
        Level::Info => (" INFO", "32"),
        Level::Debug => ("DEBUG", "34"),
        Level::Trace => ("TRACE", "35"),
    };
    let mut line = String::new();
    if ansi_enabled() {
        line.push_str(&format!(
            "\x1b[2m{time}\x1b[0m \x1b[{color}m{name}\x1b[0m \x1b[2m{target}\x1b[0m\x1b[2m:\x1b[0m {message}"
        ));
        for (key, value) in fields {
            line.push_str(&format!(" \x1b[3m{key}\x1b[0m\x1b[2m=\x1b[0m{value}"));
        }
    } else {
        line.push_str(&format!("{time} {name} {target}: {message}"));
        for (key, value) in fields {
            line.push_str(&format!(" {key}={value}"));
        }
    }
    line.push('\n');
    let mut stderr = std::io::stderr().lock();
    let _ = stderr.write_all(line.as_bytes());
}

macro_rules! info {
    ($target:expr, $($arg:tt)*) => {
        $crate::log::write($crate::log::Level::Info, $target, &format!($($arg)*), &[])
