//! Messages exchanged with the daemon and the task/state data model.

use std::collections::{BTreeMap, HashMap};
use std::fmt;
use std::path::PathBuf;

use chrono::{DateTime, Local};
use serde::{Deserialize, Serialize};

// ---------------------------------------------------------------------------
// Data model
// ---------------------------------------------------------------------------

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum TaskResult {
    Success,
    Failed(i32),
    FailedToSpawn(String),
    Killed,
    Errored,
    DependencyFailed,
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize, Deserialize)]
pub enum TaskStatus {
    Locked {
        previous_status: Box<TaskStatus>,
    },
    Stashed {
        enqueue_at: Option<DateTime<Local>>,
    },
    Queued {
        enqueued_at: DateTime<Local>,
    },
    Running {
        enqueued_at: DateTime<Local>,
        start: DateTime<Local>,
    },
    Paused {
        enqueued_at: DateTime<Local>,
        start: DateTime<Local>,
    },
    Done {
        enqueued_at: DateTime<Local>,
        start: DateTime<Local>,
        end: DateTime<Local>,
        result: TaskResult,
    },
}

#[derive(Clone, Serialize, Deserialize)]
pub struct Task {
    pub id: usize,
    pub created_at: DateTime<Local>,
    pub original_command: String,
    pub command: String,
    pub path: PathBuf,
    pub envs: HashMap<String, String>,
    pub group: String,
    pub dependencies: Vec<usize>,
    pub priority: i32,
    pub label: Option<String>,
    pub status: TaskStatus,
}

impl fmt::Debug for Task {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("Task")
            .field("id", &self.id)
            .field("original_command", &self.original_command)
            .field("command", &self.command)
            .field("path", &self.path)
            .field("envs", &"hidden")
            .field("group", &self.group)
            .field("dependencies", &self.dependencies)
            .field("label", &self.label)
            .field("status", &self.status)
            .field("priority", &self.priority)
            .finish()
    }
}

impl Task {
    pub fn is_running(&self) -> bool {
        matches!(self.status, TaskStatus::Running { .. })
    }

    pub fn is_paused(&self) -> bool {
        matches!(self.status, TaskStatus::Paused { .. })
    }

    pub fn is_done(&self) -> bool {
        matches!(self.status, TaskStatus::Done { .. })
    }

    pub fn is_stashed(&self) -> bool {
        matches!(self.status, TaskStatus::Stashed { .. })
    }

    pub fn is_queued(&self) -> bool {
        matches!(self.status, TaskStatus::Queued { .. })
    }

    pub fn failed(&self) -> bool {
        match &self.status {
            TaskStatus::Done { result, .. } => !matches!(result, TaskResult::Success),
            _ => false,
        }
    }

    pub fn start_and_end(&self) -> (Option<DateTime<Local>>, Option<DateTime<Local>>) {
        match &self.status {
            TaskStatus::Running { start, .. } | TaskStatus::Paused { start, .. } => {
                (Some(*start), None)
            }
            TaskStatus::Done { start, end, .. } => (Some(*start), Some(*end)),
            _ => (None, None),
        }
    }
}

