//! Communication with the daemon.

use std::io::{Read, Write};
use std::net::TcpStream;
use std::os::unix::net::UnixStream;

use serde::de::DeserializeOwned;
use serde::Serialize;

use crate::errors::{Report, CLIENT_RS, PUEUE_BIN};
use crate::log::{debug, warn};
use crate::settings::Settings;

pub const PROTOCOL_VERSION: &str = "0.31.1";

/// Threshold above which a warning about large payloads is logged.
const LARGE_PAYLOAD: u64 = 20 * (2u64.pow(20));

pub enum Stream {
    Unix(UnixStream),
    Tcp(TcpStream),
}

impl Read for Stream {
    fn read(&mut self, buf: &mut [u8]) -> std::io::Result<usize> {
        match self {
            Stream::Unix(s) => s.read(buf),
            Stream::Tcp(s) => s.read(buf),
        }
    }
}

impl Write for Stream {
    fn write(&mut self, buf: &[u8]) -> std::io::Result<usize> {
        match self {
            Stream::Unix(s) => s.write(buf),
            Stream::Tcp(s) => s.write(buf),
        }
    }

    fn flush(&mut self) -> std::io::Result<()> {
        match self {
            Stream::Unix(s) => s.flush(),
            Stream::Tcp(s) => s.flush(),
        }
    }
}

/// Protocol level errors. The display output matches the original messages.
#[derive(Debug)]
pub enum ProtocolError {
    Io(&'static str, std::io::Error),
    ConnectionGone,
    EmptyPayload,
    Deserialization(String),
    UnexpectedMessage(String),
    Other(String),
}

impl std::fmt::Display for ProtocolError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ProtocolError::Io(msg, err) => write!(f, "I/O error while {msg}:\n{}", io_err_msg(err)),
            ProtocolError::ConnectionGone => write!(f, "Connection went away while receiving payload."),
            ProtocolError::EmptyPayload => write!(f, "Got an empty payload"),
            ProtocolError::Deserialization(msg) => write!(f, "Couldn't deserialize message:\n{msg}"),
            ProtocolError::UnexpectedMessage(msg) => {
                write!(f, "Got unexpected but valid message. Are you up-to-date?:\n{msg}")
            }
            ProtocolError::Other(msg) => write!(f, "{msg}"),
        }
    }
}

impl ProtocolError {
    pub fn report(&self, file: &str, line: u32) -> Report {
        Report::new(self.to_string(), file, line)
    }
}

/// Render io errors the same way async runtimes do (`early eof` on unexpected EOF).
pub fn io_err_msg(err: &std::io::Error) -> String {
    if err.kind() == std::io::ErrorKind::UnexpectedEof && err.raw_os_error().is_none() {
        return "early eof".to_string();
    }
    err.to_string()
}

fn read_exact_or_eof(stream: &mut Stream, buf: &mut [u8]) -> std::io::Result<()> {
    let mut read = 0;
    while read < buf.len() {
        match stream.read(&mut buf[read..]) {
            Ok(0) => {
                return Err(std::io::Error::new(
                    std::io::ErrorKind::UnexpectedEof,
                    "early eof",
                ))
            }
            Ok(n) => read += n,
            Err(err) if err.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(err) => return Err(err),
        }
    }
    Ok(())
}

pub fn send_bytes(stream: &mut Stream, payload: &[u8]) -> Result<(), ProtocolError> {
    let header = (payload.len() as u64).to_be_bytes();
    stream
        .write_all(&header)
        .map_err(|err| ProtocolError::Io("sending request size header", err))?;
    stream
        .write_all(payload)
        .map_err(|err| ProtocolError::Io("sending payload", err))?;
    stream
        .flush()
        .map_err(|err| ProtocolError::Io("flushing stream", err))?;
    Ok(())
}

pub fn receive_bytes(stream: &mut Stream) -> Result<Vec<u8>, ProtocolError> {
    let mut header = [0u8; 8];
    read_exact_or_eof(stream, &mut header)
        .map_err(|err| ProtocolError::Io("reading request size header", err))?;
    let size = u64::from_be_bytes(header);

    if size > LARGE_PAYLOAD {
        warn!(
            "pueue_lib::network::protocol",
            "Client is sending a large payload: {size} bytes."
        );
    }

    let mut payload: Vec<u8> = Vec::new();
    let mut chunk = vec![0u8; 4096];
    while (payload.len() as u64) < size {
        let remaining = (size - payload.len() as u64).min(chunk.len() as u64) as usize;
        match stream.read(&mut chunk[..remaining]) {
            Ok(0) => return Err(ProtocolError::ConnectionGone),
            Ok(n) => payload.extend_from_slice(&chunk[..n]),
            Err(err) if err.kind() == std::io::ErrorKind::Interrupted => continue,
            Err(err) => return Err(ProtocolError::Io("reading payload", err)),
        }
    }
    Ok(payload)
}

pub struct Client {
    pub stream: Stream,
    pub daemon_version: String,
}

/// Read the shared secret.
fn read_shared_secret(settings: &Settings) -> Result<Vec<u8>, Report> {
    let path = settings.shared.shared_secret_path();
    let mut file = std::fs::File::open(&path).map_err(|err| {
        Report::new(
            format!(
                "I/O error at path {path:?} while opening secret file. Did you start the daemon at least once?:\n{err}"
            ),
            PUEUE_BIN,
            91,
        )
    })?;
    let mut buf = Vec::new();
    file.read_to_end(&mut buf).map_err(|err| {
        Report::new(
            format!("I/O error at path {path:?} while reading secret file:\n{err}"),
            PUEUE_BIN,
            91,
        )
    })?;
    Ok(buf)
}

/// Validate the daemon certificate, which is required for TLS connections.
fn load_certificate(settings: &Settings) -> Result<(), Report> {
    let path = settings.shared.daemon_cert();
    let fail = |msg: String| {
        Report::new(
            format!("Invalid or malformed certificate: Failed to parse daemon certificate:\n{msg}"),
            PUEUE_BIN,
            90,
        )
    };
    let content = match std::fs::read(&path) {
        Ok(content) => content,
        Err(err) => return Err(fail(crate::util::debug_io_error(&err))),
    };
    crate::util::validate_pem_certificate(&content).map_err(fail)
}

impl Client {
    pub fn new(settings: &Settings, show_version_warning: bool) -> Result<Client, Report> {
        if !settings.shared.use_unix_socket {
            load_certificate(settings)?;
        }
        let secret = read_shared_secret(settings)?;

        let wrap_init = |report: Report| {
            report
                .wrap("Failed to initialize stream.")
                .wrap("Failed to initialize client.")
        };

        let mut stream = if settings.shared.use_unix_socket {
            let path = settings.shared.unix_socket_path();
            match UnixStream::connect(&path) {
                Ok(stream) => Stream::Unix(stream),
                Err(err) => {
                    return Err(wrap_init(Report::new(
                        format!(
                            "I/O error at path {path:?} while connecting to daemon. Did you start it?:\n{err}"
                        ),
                        CLIENT_RS,
                        85,
                    )))
                }
            }
        } else {
            let address = format!("{}:{}", settings.shared.host, settings.shared.port);
            match TcpStream::connect(&address) {
                Ok(_stream) => {
                    // Encrypted connections aren't supported by this client.
                    return Err(wrap_init(Report::new(
                        format!(
                            "Failed to connect to the daemon on {address}. Did you start it?"
                        ),
                        CLIENT_RS,
                        85,
                    )));
                }
                Err(_) => {
                    return Err(wrap_init(Report::new(
                        format!(
                            "Failed to connect to the daemon on {address}. Did you start it?"
                        ),
                        CLIENT_RS,
                        85,
                    )))
                }
            }
        };

        if let Err(err) = send_bytes(&mut stream, &secret) {
            return Err(Report::new(err.to_string(), CLIENT_RS, 92)
                .wrap("Failed to send secret.")
                .wrap("Failed to initialize client."));
        }

        let version_bytes = match receive_bytes(&mut stream) {
            Ok(bytes) => bytes,
            Err(err) => {
                return Err(Report::new(err.to_string(), CLIENT_RS, 97)
                    .wrap("Failed to receive version during handshake with daemon.")
                    .wrap("Failed to initialize client."))
            }
        };

        let daemon_version = match String::from_utf8(version_bytes) {
            Ok(version) => version,
            Err(_) => {
                return Err(Report::new(
                    "Daemon sent invalid UTF-8. Did you use the correct secret?",
                    CLIENT_RS,
                    104,
                )
                .wrap("Failed to initialize client."))
            }
        };

        if show_version_warning && daemon_version != PROTOCOL_VERSION {
            warn!(
                "pueue_lib::network::client",
                "Different protocol version detected '{daemon_version}'. Consider updating and restarting the daemon."
            );
        }

        Ok(Client {
            stream,
            daemon_version,
        })
    }

    pub fn send_request<T: Serialize + std::fmt::Debug>(
        &mut self,
        message: &T,
    ) -> Result<(), ProtocolError> {
        debug!(
            "pueue_lib::network::protocol",
            "Sending message: {message:#?}"
        );
        let mut payload = Vec::new();
        ciborium::into_writer(message, &mut payload)
            .map_err(|err| ProtocolError::Other(format!("{err:?}")))?;
        send_bytes(&mut self.stream, &payload)
    }

    pub fn receive_response<T: DeserializeOwned + std::fmt::Debug>(
        &mut self,
    ) -> Result<T, ProtocolError> {
        let payload = receive_bytes(&mut self.stream)?;
        if payload.is_empty() {
            return Err(ProtocolError::EmptyPayload);
        }
        match ciborium::from_reader::<T, _>(payload.as_slice()) {
            Ok(message) => {
                debug!(
                    "pueue_lib::network::protocol",
                    "Received message: {message:#?}"
                );
                Ok(message)
            }
            Err(err) => {
                match ciborium::from_reader::<ciborium::Value, _>(payload.as_slice()) {
                    Ok(value) => Err(ProtocolError::UnexpectedMessage(format!("{value:#?}"))),
                    Err(_) => Err(ProtocolError::Deserialization(format!("{err:?}"))),
                }
            }
        }
    }
}
