        let wrap_init = |report: Report| {
            report
                .wrap("Failed to initialize stream.")
                .wrap("Failed to initialize client.")
        };

        let mut stream = if settings.shared.use_unix_socket {
            let path = settings.shared.unix_socket_path();
            match UnixStream::connect(&path) {
                Ok(stream) => Stream::Unix(stream),
                Err(err) => {
                    return Err(wrap_init(Report::new(
                        format!(
                            "I/O error at path {path:?} while connecting to daemon. Did you start it?:\n{err}"
                        ),
                        CLIENT_RS,
                        85,
                    )))
                }
            }
        } else {
            let address = format!("{}:{}", settings.shared.host, settings.shared.port);
            match TcpStream::connect(&address) {
                Ok(_stream) => {
                    // Encrypted connections aren't supported by this client.
                    return Err(wrap_init(Report::new(
                        format!(
                            "Failed to connect to the daemon on {address}. Did you start it?"
                        ),
                        CLIENT_RS,
                        85,
                    )));
                }
                Err(_) => {
                    return Err(wrap_init(Report::new(
                        format!(
                            "Failed to connect to the daemon on {address}. Did you start it?"
                        ),
                        CLIENT_RS,
                        85,
                    )))
                }
            }
        };

        if let Err(err) = send_bytes(&mut stream, &secret) {
            return Err(Report::new(err.to_string(), CLIENT_RS, 92)
                .wrap("Failed to send secret.")
                .wrap("Failed to initialize client."));
        }

        let version_bytes = match receive_bytes(&mut stream) {
            Ok(bytes) => bytes,
            Err(err) => {
                return Err(Report::new(err.to_string(), CLIENT_RS, 97)
                    .wrap("Failed to receive version during handshake with daemon.")
                    .wrap("Failed to initialize client."))
            }
        };

        let daemon_version = match String::from_utf8(version_bytes) {
            Ok(version) => version,
            Err(_) => {
                return Err(Report::new(
                    "Daemon sent invalid UTF-8. Did you use the correct secret?",
                    CLIENT_RS,
                    104,
                )
                .wrap("Failed to initialize client."))
            }
        };

        if show_version_warning && daemon_version != PROTOCOL_VERSION {
            warn!(
                "pueue_lib::network::client",
                "Different protocol version detected '{daemon_version}'. Consider updating and restarting the daemon."
            );
        }

        Ok(Client {
            stream,
            daemon_version,
        })
    }

    pub fn send_request<T: Serialize + std::fmt::Debug>(
        &mut self,
        message: &T,
    ) -> Result<(), ProtocolError> {
        debug!(
            "pueue_lib::network::protocol",
            "Sending message: {message:#?}"
        );
        let mut payload = Vec::new();
        ciborium::into_writer(message, &mut payload)
            .map_err(|err| ProtocolError::Other(format!("{err:?}")))?;
        send_bytes(&mut self.stream, &payload)
    }

    pub fn receive_response<T: DeserializeOwned + std::fmt::Debug>(
        &mut self,
    ) -> Result<T, ProtocolError> {
        let payload = receive_bytes(&mut self.stream)?;
        if payload.is_empty() {
            return Err(ProtocolError::EmptyPayload);
        }
        match ciborium::from_reader::<T, _>(payload.as_slice()) {
            Ok(message) => {
                debug!(
                    "pueue_lib::network::protocol",
                    "Received message: {message:#?}"
                );
                Ok(message)
            }
            Err(err) => {
                match ciborium::from_reader::<ciborium::Value, _>(payload.as_slice()) {
                    Ok(value) => Err(ProtocolError::UnexpectedMessage(format!("{value:#?}"))),
                    Err(_) => Err(ProtocolError::Deserialization(format!("{err:?}"))),
                }
            }
        }
    }
}
EOF
