//! Small helpers.

/// Format an io error the way it's shown when wrapped in an `Io` error variant.
pub fn debug_io_error(err: &std::io::Error) -> String {
    format!("Io({err:?})")
}

fn base64_value(c: u8) -> Option<u8> {
    match c {
        b'A'..=b'Z' => Some(c - b'A'),
        b'a'..=b'z' => Some(c - b'a' + 26),
        b'0'..=b'9' => Some(c - b'0' + 52),
        b'+' => Some(62),
        b'/' => Some(63),
        _ => None,
    }
}

/// Check whether the given file content contains at least one valid PEM encoded certificate.
pub fn validate_pem_certificate(content: &[u8]) -> Result<(), String> {
    let text = String::from_utf8_lossy(content);
    let begin = "-----BEGIN CERTIFICATE-----";
    let end = "-----END CERTIFICATE-----";
    let mut found = false;
    let mut rest: &str = &text;
    while let Some(start) = rest.find(begin) {
        let after = &rest[start + begin.len()..];
        let Some(stop) = after.find(end) else {
            return Err(format!("MissingSectionEnd {{ end_marker: {:?} }}", end.as_bytes()));
        };
        let body = &after[..stop];
        for c in body.bytes() {
            if c.is_ascii_whitespace() || c == b'=' {
                continue;
            }
            if base64_value(c).is_none() {
                return Err(format!("Base64Decode(\"InvalidCharacter({c})\")"));
            }
        }
        found = true;
        rest = &after[stop + end.len()..];
    }
    if !found {
        return Err("NoItemsFound".to_string());
    }
    Ok(())
}
EOF
