    Bold,
}

#[derive(Clone, Debug)]
pub struct OutputStyle {
    pub enabled: bool,
    pub dark_mode: bool,
}

impl OutputStyle {
    pub fn new(color: &str, dark_mode: bool) -> OutputStyle {
        let enabled = match color {
            "always" => true,
            "never" => false,
            _ => std::io::stdout().is_terminal(),
        };
        OutputStyle { enabled, dark_mode }
    }

    /// Map colors depending on dark mode.
    pub fn map_color(&self, color: Color) -> Color {
        if self.dark_mode {
            match color {
                Color::Green => Color::DarkGreen,
                Color::Red => Color::DarkRed,
                Color::Yellow => Color::DarkYellow,
                other => other,
            }
        } else {
            color
        }
    }

    pub fn style_text(
        &self,
        text: impl std::fmt::Display,
        color: Option<Color>,
        attribute: Option<Attribute>,
    ) -> String {
        let text = text.to_string();
        if !self.enabled {
            return text;
        }
        let mut out = String::new();
        if let Some(color) = color {
            let color = self.map_color(color);
            out.push_str(&format!("\x1b[38;5;{}m", color.ansi_value()));
        }
        if let Some(Attribute::Bold) = attribute {
            out.push_str("\x1b[1m");
        }
        out.push_str(&text);
        if attribute.is_some() {
            out.push_str("\x1b[0m");
        } else if color.is_some() {
            out.push_str("\x1b[39m");
        }
        out
    }
}
