use std::path::PathBuf;

use errors::{print_report, Report, PUEUE_BIN};
use settings::Settings;

fn main() {
    let matches = match cli::build_cli().try_get_matches() {
        Ok(matches) => matches,
        Err(err) => err.exit(),
    };

    if let Some(("completions", sub)) = matches.subcommand() {
        let shell = completions::CompletionShell::from_arg(sub.get_one::<String>("shell").unwrap());
        match sub.get_one::<PathBuf>("output_directory") {
            Some(dir) => {
                if let Err(err) = completions::write_to_dir(shell, dir) {
                    let report = Report::new(err.to_string(), PUEUE_BIN, 125).wrap(format!(
                        "Failed to generate completions for {}",
                        shell.debug_name()
                    ));
                    print_report(&report);
                    std::process::exit(1);
                }
            }
            None => completions::print_to_stdout(shell),
        }
        return;
