                json: false,
                group: None,
            };
        };
        match name {
            "add" => SubCommand::Add {
                command: strings(m, "command"),
                working_directory: m.get_one::<PathBuf>("working_directory").cloned(),
                escape: flag(m, "escape"),
                start_immediately: flag(m, "immediate"),
                follow: flag(m, "follow"),
                stashed: flag(m, "stashed"),
                delay_until: delay(m),
                group: string(m, "group"),
                dependencies: ids(m, "dependencies"),
                priority: m.get_one::<i32>("priority").copied(),
                label: string(m, "label"),
                print_task_id: flag(m, "print_task_id"),
            },
            "remove" => SubCommand::Remove {
                task_ids: ids(m, "task_ids"),
            },
            "switch" => SubCommand::Switch {
                task_id_1: *m.get_one::<usize>("task_id_1").unwrap(),
                task_id_2: *m.get_one::<usize>("task_id_2").unwrap(),
            },
            "stash" => SubCommand::Stash {
                task_ids: ids(m, "task_ids"),
                group: string(m, "group"),
                all: flag(m, "all"),
                delay_until: delay(m),
            },
            "enqueue" => SubCommand::Enqueue {
                task_ids: ids(m, "task_ids"),
                group: string(m, "group"),
                all: flag(m, "all"),
                delay_until: delay(m),
            },
            "start" => SubCommand::Start {
                task_ids: ids(m, "task_ids"),
                group: string(m, "group"),
                all: flag(m, "all"),
            },
            "restart" => SubCommand::Restart {
                task_ids: ids(m, "task_ids"),
                all_failed: flag(m, "all_failed"),
                failed_in_group: string(m, "failed_in_group"),
                start_immediately: flag(m, "start_immediately"),
                stashed: flag(m, "stashed"),
                in_place: flag(m, "in_place"),
                not_in_place: flag(m, "not_in_place"),
                edit: flag(m, "edit"),
            },
            "pause" => SubCommand::Pause {
                task_ids: ids(m, "task_ids"),
                group: string(m, "group"),
                all: flag(m, "all"),
                wait: flag(m, "wait"),
            },
            "kill" => SubCommand::Kill {
                task_ids: ids(m, "task_ids"),
                group: string(m, "group"),
                all: flag(m, "all"),
                signal: m.get_one::<Signal>("signal").copied(),
            },
            "send" => SubCommand::Send {
                task_id: *m.get_one::<usize>("task_id").unwrap(),
                input: string(m, "input").unwrap_or_default(),
            },
            "edit" => SubCommand::Edit {
                task_ids: ids(m, "task_ids"),
            },
            "env" => {
                let (sub, sm) = m.subcommand().unwrap();
                let cmd = if sub == "set" {
                    EnvCommand::Set {
                        task_id: *sm.get_one::<usize>("task_id").unwrap(),
                        key: string(sm, "key").unwrap_or_default(),
                        value: string(sm, "value").unwrap_or_default(),
                    }
                } else {
                    EnvCommand::Unset {
                        task_id: *sm.get_one::<usize>("task_id").unwrap(),
                        key: string(sm, "key").unwrap_or_default(),
                    }
                };
                SubCommand::Env { cmd }
            }
            "group" => {
                let cmd = match m.subcommand() {
                    Some(("add", sm)) => Some(GroupCommand::Add {
                        name: string(sm, "name").unwrap_or_default(),
                        parallel: sm.get_one::<usize>("parallel").copied(),
                    }),
                    Some(("remove", sm)) => Some(GroupCommand::Remove {
                        name: string(sm, "name").unwrap_or_default(),
                    }),
                    _ => None,
                };
                SubCommand::Group {
                    json: flag(m, "json"),
                    cmd,
                }
            }
            "status" => SubCommand::Status {
                query: strings(m, "query"),
                json: flag(m, "json"),
                group: string(m, "group"),
            },
            "log" => SubCommand::Log {
                task_ids: ids(m, "task_ids"),
                group: string(m, "group"),
                all: flag(m, "all"),
                json: flag(m, "json"),
                lines: m.get_one::<usize>("lines").copied(),
                full: flag(m, "full"),
            },
            "follow" => SubCommand::Follow {
