            "wait" => SubCommand::Wait {
                task_ids: ids(m, "task_ids"),
                group: string(m, "group"),
                all: flag(m, "all"),
                quiet: flag(m, "quiet"),
                status: m.get_one::<WaitTargetStatus>("status").copied(),
            },
            "clean" => SubCommand::Clean {
