                group: string(m, "group"),
            },
            _ => SubCommand::Status {
                query: Vec::new(),
                json: false,
                group: None,
            },
        }
    }
}

/// Send a request and wait for the response.
/// Any protocol error is reported at the given location.
pub fn send_and_receive(
    client: &mut Client,
    request: Request,
    file: &str,
    line: u32,
) -> Result<Response> {
    client
        .send_request(&request)
        .map_err(|err| err.report(&location(file), line))?;
    client
        .receive_response::<Response>()
        .map_err(|err| err.report(&location(file), line))
}

/// Get the current state from the daemon.
pub fn get_state(client: &mut Client) -> Result<State> {
    let response = send_and_receive(client, Request::Status, "mod.rs", 106)?;
    match response {
        Response::Status(state) => Ok(*state),
        _ => crate::errors::panic_exit(
            "internal error: entered unreachable code",
            &location("mod.rs"),
            110,
        ),
    }
}

/// Get a single task from the daemon.
pub fn get_task(client: &mut Client, task_id: usize) -> Result<Option<Task>> {
    let response = send_and_receive(client, Request::Status, "mod.rs", 120)?;
    match response {
        Response::Status(mut state) => Ok(state.tasks.remove(&task_id)),
        _ => crate::errors::panic_exit(
            "internal error: entered unreachable code",
            &location("mod.rs"),
            124,
        ),
    }
}

/// Handle the generic responses of the daemon.
/// Returns the exit code that should be used.
pub fn handle_response(style: &OutputStyle, response: Response) -> i32 {
    match response {
        Response::Success(text) => {
            println!("{text}");
            0
        }
        Response::Failure(text) => {
            eprintln!("{}", style.style_text(text, Some(Color::Red), None));
            1
        }
        Response::Close => 0,
        _ => {
            crate::log::write(
                crate::log::Level::Error,
                "pueue::client::commands",
                "Received unhandled response message",
                &[],
            );
            0
        }
    }
}

pub fn handle_command(
    client: &mut Client,
    settings: &Settings,
    style: &OutputStyle,
    subcommand: SubCommand,
) -> std::result::Result<i32, Report> {
    crate::log::write(
        crate::log::Level::Trace,
        "pueue::client::commands",
        "Handling command",
        &[("subcommand", format!("{subcommand:#?}"))],
    );

    match subcommand {
        SubCommand::Add { .. } => add::add(client, settings, style, subcommand),
        SubCommand::Remove { task_ids } => simple::remove(client, style, task_ids),
        SubCommand::Switch {
            task_id_1,
            task_id_2,
        } => simple::switch(client, style, task_id_1, task_id_2),
        SubCommand::Stash {
            task_ids,
            group,
            all,
            delay_until,
        } => simple::stash(client, style, task_ids, group, all, delay_until),
        SubCommand::Enqueue {
            task_ids,
            group,
            all,
            delay_until,
        } => simple::enqueue(client, style, task_ids, group, all, delay_until),
        SubCommand::Start {
            task_ids,
            group,
            all,
        } => simple::start(client, style, task_ids, group, all),
        SubCommand::Restart { .. } => restart::restart(client, settings, style, subcommand),
        SubCommand::Pause {
            task_ids,
            group,
            all,
            wait,
        } => simple::pause(client, style, task_ids, group, all, wait),
        SubCommand::Kill {
            task_ids,
            group,
            all,
            signal,
        } => simple::kill(client, settings, style, task_ids, group, all, signal),
        SubCommand::Send { task_id, input } => simple::send(client, style, task_id, input),
        SubCommand::Edit { task_ids } => edit::edit(client, settings, style, task_ids),
        SubCommand::Env { cmd } => simple::env(client, style, cmd),
        SubCommand::Group { json, cmd } => group::group(client, style, json, cmd),
        SubCommand::Status { query, json, group } => {
            status::status(client, settings, style, query, json, group)
        }
        SubCommand::Log {
            task_ids,
            group,
            all,
            json,
            lines,
            full,
        } => log::log(client, settings, style, task_ids, group, all, json, lines, full),
        SubCommand::Follow { task_id, lines } => follow::follow(client, settings, style, task_id, lines),
        SubCommand::Wait {
            task_ids,
            group,
            all,
            quiet,
            status,
        } => wait::wait(client, style, task_ids, group, all, quiet, status),
        SubCommand::Clean {
            successful_only,
            group,
        } => simple::clean(client, style, successful_only, group),
        SubCommand::Reset { groups, force } => reset::reset(client, settings, style, groups, force),
        SubCommand::Shutdown => simple::shutdown(client, style),
        SubCommand::Parallel {
            parallel_tasks,
            group,
        } => simple::parallel(client, style, parallel_tasks, group),
    }
}

/// Format a datetime. Use the time format for today and the datetime format otherwise.
pub fn format_datetime(settings: &Settings, datetime: &DateTime<Local>) -> String {
    let today = Local::now().date_naive();
    if datetime.date_naive() == today {
        datetime.format(&settings.client.status_time_format).to_string()
    } else {
        datetime
            .format(&settings.client.status_datetime_format)
            .to_string()
    }
}

pub fn selection(task_ids: Vec<usize>, group: Option<String>, all: bool) -> crate::messages::TaskSelection {
    use crate::messages::TaskSelection;
    if !task_ids.is_empty() {
        TaskSelection::TaskIds(task_ids)
    } else if let Some(group) = group {
        TaskSelection::Group(group)
    } else if all {
        TaskSelection::All
    } else {
        TaskSelection::Group("default".to_string())
    }
}
