/// Escape a string for usage in a posix shell.
pub fn shell_escape(input: &str) -> String {
    fn allowed(c: char) -> bool {
        matches!(c, 'a'..='z' | 'A'..='Z' | '0'..='9' | '-' | '_' | '=' | '/' | ',' | '.' | '+')
    }
    if !input.is_empty() && input.chars().all(allowed) {
        return input.to_string();
    }
    let mut escaped = String::with_capacity(input.len() + 2);
    escaped.push('\'');
    for c in input.chars() {
        match c {
            '\'' | '!' => {
                escaped.push_str("'\\");
                escaped.push(c);
                escaped.push('\'');
            }
            _ => escaped.push(c),
        }
    }
    escaped.push('\'');
    escaped
}

pub fn add(
    client: &mut Client,
    settings: &Settings,
    style: &OutputStyle,
    subcommand: SubCommand,
) -> Result<i32> {
    let SubCommand::Add {
        command,
        working_directory,
        escape,
        start_immediately,
        follow,
        stashed,
        delay_until,
        group,
        dependencies,
        priority,
        label,
        print_task_id,
    } = subcommand
    else {
        unreachable!()
    };

    let path = match working_directory {
        Some(path) => std::fs::canonicalize(&path).map_err(|err| {
            Report::new(err.to_string(), &location("add.rs"), 42)
