//! Parsing of delay expressions.
//!
//! A delay is either a number of seconds or a date expression similar to
//! the ones understood by `date -d`.

use chrono::{DateTime, Datelike, Duration, Local, Months, NaiveDate, NaiveTime, TimeZone, Weekday};

const ERROR: &str = "could not parse as seconds or date expression";

pub fn parse_delay_until(src: &str) -> Result<DateTime<Local>, String> {
    if let Ok(seconds) = src.parse::<i64>() {
        return Ok(Local::now() + Duration::seconds(seconds));
    }
    let now = Local::now();
    match Parser::new(src, now).parse() {
        Some(datetime) => Ok(datetime),
        None => Err(ERROR.to_string()),
    }
}

#[derive(Debug, Clone, PartialEq)]
enum Token {
    Num(String),
    Word(String),
    Colon,
    Dash,
    Slash,
    Dot,
    Comma,
    Plus,
}

fn tokenize(input: &str) -> Option<Vec<Token>> {
    let chars: Vec<char> = input.chars().collect();
    let mut tokens = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let c = chars[i];
        if c.is_whitespace() {
            i += 1;
        } else if c.is_ascii_digit() {
            let start = i;
            while i < chars.len() && chars[i].is_ascii_digit() {
                i += 1;
            }
            tokens.push(Token::Num(chars[start..i].iter().collect()));
        } else if c.is_alphabetic() {
            let start = i;
            while i < chars.len() && chars[i].is_alphabetic() {
                i += 1;
            }
            let word: String = chars[start..i].iter().collect();
            tokens.push(Token::Word(word.to_lowercase()));
        } else {
            let token = match c {
                ':' => Token::Colon,
                '-' => Token::Dash,
                '/' => Token::Slash,
                '.' => Token::Dot,
                ',' => Token::Comma,
                '+' => Token::Plus,
                _ => return None,
            };
            tokens.push(token);
            i += 1;
        }
    }
    Some(tokens)
}

#[derive(Debug, Clone, Copy, PartialEq)]
enum Unit {
    Second,
    Minute,
    Hour,
    Day,
    Week,
    Month,
    Year,
}

fn unit_from_word(word: &str) -> Option<Unit> {
    match word {
        "s" | "sec" | "secs" => return Some(Unit::Second),
        "m" | "min" | "mins" => return Some(Unit::Minute),
        "h" => return Some(Unit::Hour),
        "d" => return Some(Unit::Day),
        "w" => return Some(Unit::Week),
        "mo" => return Some(Unit::Month),
        "y" => return Some(Unit::Year),
        _ => {}
    }
    let units = [
        ("seconds", Unit::Second),
        ("minutes", Unit::Minute),
        ("hours", Unit::Hour),
        ("days", Unit::Day),
        ("weeks", Unit::Week),
        ("months", Unit::Month),
        ("years", Unit::Year),
    ];
    for (name, unit) in units {
        let singular = &name[..name.len() - 1];
        if singular.starts_with(word) || name == word {
            return Some(unit);
        }
    }
    None
}

fn weekday_from_word(word: &str) -> Option<Weekday> {
    if word.len() < 3 {
        return None;
    }
    let days = [
        ("monday", Weekday::Mon),
        ("tuesday", Weekday::Tue),
        ("wednesday", Weekday::Wed),
        ("thursday", Weekday::Thu),
        ("friday", Weekday::Fri),
        ("saturday", Weekday::Sat),
        ("sunday", Weekday::Sun),
    ];
    days.iter()
        .find(|(name, _)| name.starts_with(word))
        .map(|(_, day)| *day)
}

fn month_from_word(word: &str) -> Option<u32> {
    if word.len() < 3 {
        return None;
    }
    let months = [
        "january",
        "february",
        "march",
        "april",
        "may",
        "june",
        "july",
        "august",
        "september",
        "october",
        "november",
        "december",
    ];
    months
        .iter()
        .position(|name| name.starts_with(word))
        .map(|index| index as u32 + 1)
}

#[derive(Debug, Clone, Copy)]
struct Time {
    hour: u32,
    minute: u32,
    second: u32,
    /// Whether the time contained a separator or an am/pm marker.
    explicit: bool,
    meridiem: bool,
}

enum DateKind {
    /// Relative interval without "ago"
    Interval,
    /// Any other kind of date
    Other,
}

struct Parser {
    tokens: Vec<Token>,
    pos: usize,
    now: DateTime<Local>,
    valid: bool,
}

impl Parser {
    fn new(input: &str, now: DateTime<Local>) -> Parser {
        match tokenize(input) {
            Some(tokens) => Parser {
                tokens,
                pos: 0,
                now,
                valid: true,
            },
            None => Parser {
                tokens: Vec::new(),
                pos: 0,
                now,
                valid: false,
            },
        }
    }

    fn peek(&self) -> Option<&Token> {
        self.tokens.get(self.pos)
    }

    fn peek_at(&self, offset: usize) -> Option<&Token> {
        self.tokens.get(self.pos + offset)
    }

    fn next(&mut self) -> Option<Token> {
        let token = self.tokens.get(self.pos).cloned();
        if token.is_some() {
            self.pos += 1;
        }
        token
    }

    fn at_end(&self) -> bool {
        self.pos >= self.tokens.len()
    }

    fn next_num(&mut self) -> Option<String> {
        match self.next() {
            Some(Token::Num(n)) => Some(n),
            _ => None,
        }
    }

    fn parse(&mut self) -> Option<DateTime<Local>> {
        if !self.valid || self.tokens.is_empty() {
            return None;
        }

        // A date might come first.
        let start = self.pos;
        if let Some((date, kind)) = self.parse_date() {
            if self.at_end() {
                return Some(date);
            }
            let time = match kind {
                DateKind::Interval => {
                    // Only explicit clock times are allowed after plain intervals.
                    let time = self.parse_time()?;
                    if !time.explicit || (time.meridiem && !time_has_separator(&time)) {
                        return None;
                    }
                    time
                }
                DateKind::Other => {
                    let time = self.parse_time()?;
                    if !time.explicit {
                        return None;
                    }
                    time
                }
            };
            self.parse_timezone();
            if !self.at_end() {
                return None;
            }
            return combine(date, time);
        }
        self.pos = start;

        // Otherwise a time, optionally followed by a date.
        let time = self.parse_time()?;
        if self.at_end() {
            let date = self.now;
            return combine(date, time);
        }
        if !time.meridiem {
            return None;
        }
        if let Some(Token::Word(w)) = self.peek() {
            if w == "on" {
                self.next();
                if self.at_end() {
                    return combine(self.now, time);
                }
            }
        }
        let (date, _) = self.parse_date()?;
        if !self.at_end() {
            return None;
        }
        combine(date, time)
    }

    fn parse_timezone(&mut self) {
        match self.peek() {
            Some(Token::Word(w)) if w == "z" => {
                self.next();
            }
            Some(Token::Plus) | Some(Token::Dash) => {
                let save = self.pos;
                self.next();
                match self.next() {
                    Some(Token::Num(n)) if n.len() == 4 => {}
                    Some(Token::Num(n)) if n.len() <= 2 => {
                        if let Some(Token::Colon) = self.peek() {
                            self.next();
                            if self.next_num().is_none() {
                                self.pos = save;
                            }
                        }
                    }
                    _ => self.pos = save,
                }
            }
            _ => {}
        }
    }

    /// Parse a date expression. On failure, the position is undefined.
    fn parse_date(&mut self) -> Option<(DateTime<Local>, DateKind)> {
        let token = self.peek()?.clone();
        match token {
            Token::Word(word) => {
                self.next();
                self.parse_word_date(&word)
            }
            Token::Num(num) => {
                match self.peek_at(1) {
                    Some(Token::Dash) => {
                        self.next();
                        self.parse_iso_date(&num).map(|d| (d, DateKind::Other))
                    }
                    Some(Token::Slash) => {
                        self.next();
                        self.parse_us_date(&num).map(|d| (d, DateKind::Other))
                    }
                    Some(Token::Word(word)) => {
                        let word = word.clone();
                        if let Some(unit) = unit_from_word(&word) {
                            self.next();
                            self.next();
                            let amount: i64 = num.parse().ok()?;
                            let mut ago = false;
                            if let Some(Token::Word(w)) = self.peek() {
                                if w == "ago" {
                                    ago = true;
                                    self.next();
                                }
                            }
                            let amount = if ago { -amount } else { amount };
                            let date = add_interval(self.now, unit, amount)?;
                            let kind = if ago { DateKind::Other } else { DateKind::Interval };
                            Some((date, kind))
                        } else if let Some(month) = month_from_word(&word) {
                            self.next();
                            self.next();
                            let day: u32 = num.parse().ok()?;
                            let mut year = self.now.year();
                            if let Some(Token::Num(y)) = self.peek() {
                                let y = y.clone();
                                self.next();
                                year = parse_year(&y)?;
                            }
                            let date = NaiveDate::from_ymd_opt(year, month, day)?;
                            Some((at_midnight(date)?, DateKind::Other))
                        } else {
                            None
                        }
                    }
                    _ => None,
                }
            }
            _ => None,
        }
    }

    fn parse_word_date(&mut self, word: &str) -> Option<(DateTime<Local>, DateKind)> {
        let today = self.now;
        match word {
            "now" => return Some((today, DateKind::Other)),
            "today" | "midnight" | "midday" => return Some((today, DateKind::Other)),
            "tomorrow" => return Some((today + Duration::days(1), DateKind::Other)),
            "yesterday" => return Some((today - Duration::days(1), DateKind::Other)),
            "next" | "last" | "this" => {
                let direction: i64 = match word {
                    "next" => 1,
                    "last" => -1,
                    _ => 0,
                };
                return match self.peek()?.clone() {
                    Token::Word(next) => {
                        self.next();
                        if let Some(weekday) = weekday_from_word(&next) {
                            Some((next_weekday(today, weekday, direction), DateKind::Other))
                        } else if month_from_word(&next).is_some() {
                            Some((today, DateKind::Other))
                        } else if let Some(unit) = unit_from_word(&next) {
                            Some((add_interval(today, unit, direction)?, DateKind::Other))
                        } else {
                            None
                        }
                    }
                    Token::Num(_) => Some((today, DateKind::Other)),
                    _ => None,
                };
            }
            _ => {}
        }

        if let Some(weekday) = weekday_from_word(word) {
            return Some((next_weekday(today, weekday, 0), DateKind::Other));
        }

        if let Some(month) = month_from_word(word) {
            let mut year = today.year();
            let day = match self.peek() {
                Some(Token::Num(day)) => {
                    let day = day.clone();
                    // A day is only consumed if it's not the start of a time.
                    if matches!(self.peek_at(1), Some(Token::Colon) | Some(Token::Dot)) {
                        1
                    } else if matches!(self.peek_at(1), Some(Token::Word(w)) if w == "am" || w == "pm") {
                        1
                    } else {
                        self.next();
                        let day: u32 = day.parse().ok()?;
                        if let Some(Token::Comma) = self.peek() {
                            self.next();
                            let y = self.next_num()?;
                            year = parse_year(&y)?;
                        }
                        day
                    }
                }
                Some(Token::Comma) => return None,
                _ => 1,
            };
            let date = NaiveDate::from_ymd_opt(year, month, day)?;
            return Some((at_midnight(date)?, DateKind::Other));
        }

        if let Some(unit) = unit_from_word(word) {
            if let Some(Token::Word(w)) = self.peek() {
                if w == "ago" {
                    return None;
                }
            }
            return Some((add_interval(today, unit, 1)?, DateKind::Interval));
        }

        None
    }

    fn parse_iso_date(&mut self, year: &str) -> Option<DateTime<Local>> {
        // The dash has already been consumed.
        let month = self.next_num()?;
        match self.next() {
            Some(Token::Dash) => {}
            _ => return None,
        }
        let day = self.next_num()?;
        let year = parse_year(year)?;
        let date = NaiveDate::from_ymd_opt(year, month.parse().ok()?, day.parse().ok()?)?;

        // Optional `T` separator in front of the time.
        if let Some(Token::Word(w)) = self.peek() {
            if w == "t" {
                self.next();
                if self.at_end() {
                    return at_midnight(date);
                }
                let save = self.pos;
                let time = self.parse_time()?;
                if !time.explicit || (!time.meridiem && !time_has_separator(&time)) {
                    return None;
                }
                self.pos = save;
            }
        }
        at_midnight(date)
    }

    fn parse_us_date(&mut self, month: &str) -> Option<DateTime<Local>> {
        // The slash has already been consumed.
        let day = self.next_num()?;
        let mut year = self.now.year();
        if let Some(Token::Slash) = self.peek() {
            self.next();
            let y = self.next_num()?;
            year = parse_year(&y)?;
        }
        let date = NaiveDate::from_ymd_opt(year, month.parse().ok()?, day.parse().ok()?)?;
        if let Some(Token::Word(w)) = self.peek() {
            if w == "t" {
                self.next();
            }
        }
        at_midnight(date)
    }

    /// Parse a clock time.
    fn parse_time(&mut self) -> Option<Time> {
        let hour: u32 = self.next_num()?.parse().ok()?;
        let mut minute = 0;
        let mut second = 0;
        let mut explicit = false;
        let mut separated = false;

        match self.peek() {
            Some(Token::Colon) => {
                self.next();
                minute = self.next_num()?.parse().ok()?;
                explicit = true;
                separated = true;
                if let Some(Token::Colon) = self.peek() {
                    self.next();
                    second = self.next_num()?.parse().ok()?;
                    if let Some(Token::Dot) = self.peek() {
                        self.next();
                        let frac = self.next_num()?;
                        if frac.len() > 3 {
                            return None;
                        }
                    }
                }
            }
            Some(Token::Dot) => {
                self.next();
                minute = self.next_num()?.parse().ok()?;
                explicit = true;
                separated = true;
            }
            _ => {}
        }

        if minute > 59 || second > 59 {
            return None;
        }

        let mut meridiem = false;
        if let Some(Token::Word(w)) = self.peek() {
            if w == "am" || w == "pm" {
                meridiem = true;
                explicit = true;
                let w = w.clone();
                self.next();
                if w == "pm" && hour < 12 {
                    return Some(Time {
                        hour: hour + 12,
                        minute,
                        second,
                        explicit,
                        meridiem: true,
                    })
                    .map(|t| mark_separated(t, separated));
                }
                if w == "am" && hour == 12 {
                    return Some(mark_separated(
                        Time {
                            hour: 0,
                            minute,
                            second,
                            explicit,
                            meridiem: true,
                        },
                        separated,
                    ));
                }
            }
        }

        Some(mark_separated(
            Time {
                hour,
                minute,
                second,
                explicit,
                meridiem,
            },
            separated,
        ))
    }
}

/// Encode whether the time used a separator in the `explicit` and `meridiem` flags.
/// A time is "separated" if it contained `:` or `.`.
fn mark_separated(time: Time, separated: bool) -> Time {
    SEPARATED.with(|s| s.set(separated));
    time
}

thread_local! {
    static SEPARATED: std::cell::Cell<bool> = const { std::cell::Cell::new(false) };
}

fn time_has_separator(_time: &Time) -> bool {
    SEPARATED.with(|s| s.get())
}

fn parse_year(year: &str) -> Option<i32> {
    let value: i32 = year.parse().ok()?;
    if year.len() <= 2 {
        Some(2000 + value)
    } else {
        Some(value)
    }
}

fn at_midnight(date: NaiveDate) -> Option<DateTime<Local>> {
    Local
        .from_local_datetime(&date.and_hms_opt(0, 0, 0)?)
        .earliest()
}

fn add_interval(now: DateTime<Local>, unit: Unit, amount: i64) -> Option<DateTime<Local>> {
    match unit {
        Unit::Second => Some(now + Duration::seconds(amount)),
        Unit::Minute => Some(now + Duration::minutes(amount)),
        Unit::Hour => Some(now + Duration::hours(amount)),
        Unit::Day => Some(now + Duration::days(amount)),
        Unit::Week => Some(now + Duration::weeks(amount)),
        Unit::Month => {
            if amount >= 0 {
                now.checked_add_months(Months::new(amount as u32))
            } else {
                now.checked_sub_months(Months::new((-amount) as u32))
            }
        }
        Unit::Year => {
            let months = amount.checked_mul(12)?;
            if months >= 0 {
                now.checked_add_months(Months::new(months as u32))
            } else {
                now.checked_sub_months(Months::new((-months) as u32))
            }
        }
    }
}

fn next_weekday(now: DateTime<Local>, weekday: Weekday, direction: i64) -> DateTime<Local> {
    let current = now.weekday().num_days_from_monday() as i64;
    let target = weekday.num_days_from_monday() as i64;
    let mut diff = (target - current + 7) % 7;
    if direction < 0 {
        diff -= 7;
        if diff == -7 && direction < 0 {
            diff = -7;
        }
    } else if diff == 0 {
        diff = 7;
    }
    let date = now.date_naive() + Duration::days(diff);
    at_midnight(date).unwrap_or(now)
}

fn combine(date: DateTime<Local>, time: Time) -> Option<DateTime<Local>> {
    let extra_days = (time.hour / 24) as i64;
    let hour = time.hour % 24;
    let naive_time = NaiveTime::from_hms_opt(hour, time.minute, time.second)?;
    let day = date.date_naive().checked_add_signed(Duration::days(extra_days))?;
    Local.from_local_datetime(&day.and_time(naive_time)).earliest()
}
