//! Rendering of tables with horizontal lines only.

use unicode_width::UnicodeWidthStr;

use crate::style::{Color, OutputStyle};

#[derive(Clone, Debug)]
pub struct Cell {
    pub content: String,
    pub color: Option<Color>,
}

impl Cell {
    pub fn new(content: impl ToString) -> Cell {
        Cell {
            content: content.to_string(),
            color: None,
        }
    }

    pub fn colored(content: impl ToString, color: Color) -> Cell {
        Cell {
            content: content.to_string(),
            color: Some(color),
        }
    }

    fn lines(&self) -> Vec<String> {
        self.content.split('\n').map(|line| line.to_string()).collect()
    }
}

pub struct Table {
    pub header: Vec<Cell>,
    pub rows: Vec<Vec<Cell>>,
    pub max_height: Option<usize>,
}

fn truncate_to_width(line: &str, width: usize) -> String {
    let mut out = String::new();
    let mut current = 0;
    for c in line.chars() {
        let w = UnicodeWidthStr::width(c.to_string().as_str());
        if current + w > width {
            break;
        }
        current += w;
        out.push(c);
    }
    out
}

impl Table {
    pub fn new(header: Vec<Cell>) -> Table {
        Table {
            header,
            rows: Vec::new(),
            max_height: None,
        }
    }

    pub fn render(&self, style: &OutputStyle) -> String {
        let columns = self.header.len();
        let mut widths = vec![0usize; columns];
        for (index, cell) in self.header.iter().enumerate() {
            for line in cell.lines() {
                widths[index] = widths[index].max(line.width());
            }
        }
        for row in &self.rows {
            for (index, cell) in row.iter().enumerate().take(columns) {
                for line in cell.lines() {
                    widths[index] = widths[index].max(line.width());
                }
            }
        }

        let total: usize = widths.iter().map(|w| w + 2).sum::<usize>() + columns.saturating_sub(1);
        let horizontal = "─".repeat(total);
        let header_line = "═".repeat(total);

        let mut out: Vec<String> = Vec::new();
        out.push(horizontal.clone());
        out.extend(self.render_row(&self.header, &widths, style, None));
        out.push(header_line);
        for (index, row) in self.rows.iter().enumerate() {
            out.extend(self.render_row(row, &widths, style, self.max_height));
            if index + 1 < self.rows.len() {
                out.push(horizontal.clone());
            }
        }
        out.push(horizontal);
        out.join("\n")
    }

    fn render_row(
        &self,
        row: &[Cell],
        widths: &[usize],
        style: &OutputStyle,
        max_height: Option<usize>,
    ) -> Vec<String> {
        let mut cell_lines: Vec<Vec<String>> = Vec::new();
        for (index, width) in widths.iter().enumerate() {
