use crate::network::Client;
use crate::settings::Settings;
use crate::style::{Color, OutputStyle};

pub const STATE_RS: &str = "pueue/src/client/commands/state/mod.rs";

#[derive(Clone)]
pub struct TableBuilder<'a> {
    settings: &'a Settings,
    style: &'a OutputStyle,
    id: bool,
    status: bool,
    priority: bool,
    enqueue_at: bool,
    dependencies: bool,
    label: bool,
    command: bool,
    path: bool,
    start: bool,
    end: bool,
    /// Whether columns have been explicitly selected.
    explicit: bool,
}

pub fn format_start_end(settings: &Settings, time: &chrono::DateTime<chrono::Local>) -> String {
    super::format_datetime(settings, time)
}

impl<'a> TableBuilder<'a> {
    pub fn new(settings: &'a Settings, style: &'a OutputStyle) -> TableBuilder<'a> {
        TableBuilder {
            settings,
            style,
            id: true,
            status: true,
            priority: false,
            enqueue_at: false,
            dependencies: false,
            label: false,
            command: true,
            path: true,
            start: true,
            end: true,
            explicit: false,
        }
    }

    pub fn set_columns(&mut self, columns: &[Column]) {
        if columns.is_empty() {
            return;
        }
        self.explicit = true;
        self.id = false;
        self.status = false;
        self.priority = false;
        self.enqueue_at = false;
        self.dependencies = false;
        self.label = false;
        self.command = false;
        self.path = false;
        self.start = false;
        self.end = false;
        for column in columns {
            match column {
                Column::Id => self.id = true,
                Column::Status => self.status = true,
                Column::Priority => self.priority = true,
                Column::EnqueueAt => self.enqueue_at = true,
                Column::Dependencies => self.dependencies = true,
                Column::Label => self.label = true,
                Column::Command => self.command = true,
                Column::Path => self.path = true,
                Column::Start => self.start = true,
                Column::End => self.end = true,
            }
        }
    }

    fn determine_special_columns(&mut self, tasks: &[Task]) {
        if self.explicit {
            return;
        }
        if tasks.iter().any(|task| task.priority != 0) {
            self.priority = true;
        }
        if tasks.iter().any(|task| {
            matches!(
                task.status,
                TaskStatus::Stashed {
                    enqueue_at: Some(_)
                }
            )
        }) {
            self.enqueue_at = true;
        }
        if tasks.iter().any(|task| !task.dependencies.is_empty()) {
            self.dependencies = true;
        }
        if tasks.iter().any(|task| task.label.is_some()) {
            self.label = true;
        }
    }

    pub fn build(mut self, tasks: &[Task]) -> Table {
        self.determine_special_columns(tasks);

        let mut header = Vec::new();
        let names = [
            (self.id, "Id"),
            (self.status, "Status"),
            (self.priority, "Prio"),
            (self.enqueue_at, "Enqueue At"),
            (self.dependencies, "Deps"),
            (self.label, "Label"),
            (self.command, "Command"),
            (self.path, "Path"),
            (self.start, "Start"),
            (self.end, "End"),
        ];
        for (enabled, name) in names {
            if enabled {
                header.push(Cell::new(name));
            }
        }

        let mut table = Table::new(header);
        table.max_height = self.settings.client.max_status_lines;

        for task in tasks {
            let mut row = Vec::new();
            if self.id {
                row.push(Cell::new(task.id));
            }
            if self.status {
                let (text, color) = status_text_and_color(&task.status);
                row.push(Cell::colored(text, color));
            }
            if self.priority {
                row.push(Cell::new(task.priority));
            }
            if self.enqueue_at {
                let text = match &task.status {
                    TaskStatus::Stashed {
                        enqueue_at: Some(enqueue_at),
                    } => format_start_end(self.settings, enqueue_at),
                    _ => String::new(),
                };
                row.push(Cell::new(text));
            }
            if self.dependencies {
                let text = task
                    .dependencies
                    .iter()
                    .map(|id| id.to_string())
                    .collect::<Vec<_>>()
                    .join(", ");
                row.push(Cell::new(text));
            }
            if self.label {
                row.push(Cell::new(task.label.clone().unwrap_or_default()));
            }
            if self.command {
                if self.settings.client.show_expanded_aliases {
                    row.push(Cell::new(&task.command));
                } else {
                    row.push(Cell::new(&task.original_command));
                }
            }
            if self.path {
                row.push(Cell::new(task.path.to_string_lossy()));
            }
            let (start, end) = task.start_and_end();
            if self.start {
                row.push(Cell::new(
                    start
                        .map(|start| format_start_end(self.settings, &start))
                        .unwrap_or_default(),
                ));
            }
            if self.end {
                row.push(Cell::new(
                    end.map(|end| format_start_end(self.settings, &end))
                        .unwrap_or_default(),
                ));
            }
            table.rows.push(row);
        }

        table
    }
}

pub fn status_text_and_color(status: &TaskStatus) -> (String, Color) {
    match status {
        TaskStatus::Running { .. } => ("Running".to_string(), Color::Green),
        TaskStatus::Paused { .. } => ("Paused".to_string(), Color::White),
        TaskStatus::Locked { .. } => ("Locked".to_string(), Color::White),
        TaskStatus::Stashed { .. } => ("Stashed".to_string(), Color::Yellow),
        TaskStatus::Queued { .. } => ("Queued".to_string(), Color::Yellow),
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => ("Success".to_string(), Color::Green),
            TaskResult::DependencyFailed => ("Dependency failed".to_string(), Color::Red),
            TaskResult::FailedToSpawn(_) => ("Failed to spawn".to_string(), Color::Red),
            TaskResult::Failed(code) => (format!("Failed ({code})"), Color::Red),
            TaskResult::Killed => ("Killed".to_string(), Color::Red),
            TaskResult::Errored => ("Errored".to_string(), Color::Red),
        },
    }
}

fn sort_tasks_by_group(tasks: Vec<Task>) -> BTreeMap<String, Vec<Task>> {
    let mut sorted: BTreeMap<String, Vec<Task>> = BTreeMap::new();
    for task in tasks {
        sorted.entry(task.group.clone()).or_default().push(task);
    }
    sorted
}

pub fn status(
    client: &mut Client,
    settings: &Settings,
    style: &OutputStyle,
    query: Vec<String>,
    json: bool,
    group: Option<String>,
) -> Result<i32> {
    let state = super::get_state(client)?;
    print_state(state, settings, style, query, json, group)?;
    Ok(0)
}

pub fn print_state(
    state: State,
    settings: &Settings,
    style: &OutputStyle,
    query: Vec<String>,
    json: bool,
    group_only: Option<String>,
) -> Result<()> {
    let mut table_builder = TableBuilder::new(settings, style);
    let mut tasks: Vec<Task> = state.tasks.values().cloned().collect();

    let query_result = apply_query(&query.join(" "))?;
    table_builder.set_columns(&query_result.columns);
    tasks = query_result.apply(tasks);

    if json {
        let mut state = state;
        state.tasks = tasks.into_iter().map(|task| (task.id, task)).collect();
        println!("{}", serde_json::to_string(&state).unwrap_or_default());
        return Ok(());
    }

    if let Some(group_name) = group_only {
        let mut sorted = sort_tasks_by_group(tasks);
        let Some(group) = state.groups.get(&group_name) else {
            eprintln!("There exists no group \"{group_name}\"");
            return Ok(());
        };
        let tasks = sorted.remove(&group_name).unwrap_or_default();
        println!("{}", format_group_header(style, &group_name, group));
        if tasks.is_empty() {
            println!("Task list is empty. Add tasks with `pueue add -g {group_name} -- [cmd]`");
            return Ok(());
        }
        println!("{}", table_builder.build(&tasks).render(style));
        return Ok(());
    }

    if state.tasks.is_empty() {
        let Some(group) = state.groups.get("default") else {
            panic_exit(
                "called `Option::unwrap()` on a `None` value",
                STATE_RS,
                137,
            );
        };
        println!("{}\n", format_group_header(style, "default", group));
        println!("Task list is empty. Add tasks with `pueue add -- [cmd]`");
        return Ok(());
    }

    let sorted = sort_tasks_by_group(tasks);

    if let Some(tasks) = sorted.get("default") {
        let Some(group) = state.groups.get("default") else {
            panic_exit(
                "called `Option::unwrap()` on a `None` value",
                STATE_RS,
                154,
            );
        };
        println!("{}", format_group_header(style, "default", group));
        println!("{}", table_builder.clone().build(tasks).render(style));
        if sorted.len() > 1 {
            println!();
        }
    }

    let mut iter = sorted.iter().filter(|(name, _)| name.as_str() != "default").peekable();
    while let Some((name, tasks)) = iter.next() {
        let Some(group) = state.groups.get(name) else {
            panic_exit(
                "called `Option::unwrap()` on a `None` value",
                STATE_RS,
                173,
            );
        };
        println!("{}", format_group_header(style, name, group));
        println!("{}", table_builder.clone().build(tasks).render(style));
        if iter.peek().is_some() {
            println!();
        }
    }

    Ok(())
}
