        sorted.entry(task.group.clone()).or_default().push(task);
    }
    sorted
}

pub fn status(
    client: &mut Client,
    settings: &Settings,
    style: &OutputStyle,
    query: Vec<String>,
    json: bool,
    group: Option<String>,
) -> Result<i32> {
    let state = super::get_state(client)?;
    print_state(state, settings, style, query, json, group)?;
    Ok(0)
}

pub fn print_state(
    state: State,
    settings: &Settings,
    style: &OutputStyle,
    query: Vec<String>,
    json: bool,
    group_only: Option<String>,
) -> Result<()> {
    let mut table_builder = TableBuilder::new(settings, style);
    let mut tasks: Vec<Task> = state.tasks.values().cloned().collect();

    let query_result = apply_query(&query.join(" "))?;
    table_builder.set_columns(&query_result.columns);
    tasks = query_result.apply(tasks);

    if json {
        let mut state = state;
        state.tasks = tasks.into_iter().map(|task| (task.id, task)).collect();
        println!("{}", serde_json::to_string(&state).unwrap_or_default());
        return Ok(());
    }

    if let Some(group_name) = group_only {
        let mut sorted = sort_tasks_by_group(tasks);
        let Some(group) = state.groups.get(&group_name) else {
            eprintln!("There exists no group \"{group_name}\"");
            return Ok(());
        };
        let tasks = sorted.remove(&group_name).unwrap_or_default();
        println!("{}", format_group_header(style, &group_name, group));
        if tasks.is_empty() {
            println!("Task list is empty. Add tasks with `pueue add -g {group_name} -- [cmd]`");
            return Ok(());
        }
        println!("{}", table_builder.build(&tasks).render(style));
        return Ok(());
    }

    if state.tasks.is_empty() {
        let Some(group) = state.groups.get("default") else {
            panic_exit(
                "called `Option::unwrap()` on a `None` value",
                STATE_RS,
                137,
            );
        };
        println!("{}\n", format_group_header(style, "default", group));
        println!("Task list is empty. Add tasks with `pueue add -- [cmd]`");
        return Ok(());
    }

    let sorted = sort_tasks_by_group(tasks);

    if let Some(tasks) = sorted.get("default") {
        let Some(group) = state.groups.get("default") else {
            panic_exit(
                "called `Option::unwrap()` on a `None` value",
                STATE_RS,
                154,
            );
        };
        println!("{}", format_group_header(style, "default", group));
        println!("{}", table_builder.clone().build(tasks).render(style));
        if sorted.len() > 1 {
            println!();
        }
    }

    let mut iter = sorted.iter().filter(|(name, _)| name.as_str() != "default").peekable();
    while let Some((name, tasks)) = iter.next() {
        let Some(group) = state.groups.get(name) else {
            panic_exit(
                "called `Option::unwrap()` on a `None` value",
                STATE_RS,
                173,
            );
        };
        println!("{}", format_group_header(style, name, group));
        println!("{}", table_builder.clone().build(tasks).render(style));
        if iter.peek().is_some() {
            println!();
        }
    }

    Ok(())
}
EOF
