//! The `log` command.

use std::collections::BTreeMap;
use std::fs::File;
use std::io::{Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};

use super::table::{Cell, Table};
use super::{handle_response, selection, send_and_receive};
use crate::errors::Result;
use crate::messages::{LogRequest, Request, Response, Task, TaskLogResponse, TaskResult, TaskStatus};
use crate::network::Client;
use crate::settings::Settings;
use crate::style::{Attribute, Color, OutputStyle};

pub fn log_file_path(pueue_directory: &Path, task_id: usize) -> PathBuf {
    pueue_directory.join("task_logs").join(format!("{task_id}.log"))
}

pub fn get_log_file_handle(task_id: usize, pueue_directory: &Path) -> std::result::Result<File, String> {
    let path = log_file_path(pueue_directory, task_id);
    File::open(&path).map_err(|err| {
        format!("I/O error at path {path:?} while getting log file handle:\n{err}")
    })
}

pub fn determine_log_line_amount(full: bool, lines: &Option<usize>) -> Option<usize> {
    if full {
        None
    } else if let Some(lines) = lines {
        Some(*lines)
    } else {
        Some(15)
    }
}

#[allow(clippy::too_many_arguments)]
pub fn log(
    client: &mut Client,
    settings: &Settings,
    style: &OutputStyle,
    task_ids: Vec<usize>,
    group: Option<String>,
    all: bool,
    json: bool,
    lines: Option<usize>,
    full: bool,
) -> Result<i32> {
    let lines = determine_log_line_amount(full, &lines);
    let request = Request::Log(LogRequest {
        tasks: selection(task_ids.clone(), group.clone(), all),
        send_logs: !settings.client.read_local_logs,
        lines,
    });
    let response = send_and_receive(client, request, "log/mod.rs", 46)?;
    match response {
        Response::Log(task_logs) => {
            print_logs(task_logs, settings, style, &task_ids, &group, json, lines);
            Ok(0)
        }
        other => Ok(handle_response(style, other)),
    }
}

fn print_logs(
    task_logs: BTreeMap<usize, TaskLogResponse>,
    settings: &Settings,
    style: &OutputStyle,
    task_ids: &[usize],
    group: &Option<String>,
    json: bool,
    lines: Option<usize>,
) {
    if json {
        print_log_json(task_logs, settings, lines);
        return;
    }

    if task_logs.is_empty() {
        if !task_ids.is_empty() {
            eprintln!("There are no finished tasks for your specified ids");
        } else if let Some(group) = group {
            eprintln!("There are no finished tasks for group '{group}'");
        } else {
            eprintln!("There are no finished tasks");
        }
        return;
    }

    let mut iter = task_logs.iter().peekable();
    while let Some((_, task_log)) = iter.next() {
        let printed = print_log(task_log, style, settings, lines);
        if printed && iter.peek().is_some() {
            println!();
        }
    }
}

fn shows_log(task: &Task) -> bool {
    matches!(
        task.status,
        TaskStatus::Done { .. } | TaskStatus::Running { .. } | TaskStatus::Paused { .. }
    )
}

fn print_log(
    task_log: &TaskLogResponse,
    style: &OutputStyle,
    settings: &Settings,
    lines: Option<usize>,
) -> bool {
    let task = &task_log.task;
    if !shows_log(task) {
        return false;
    }

    print_task_info(task, style);

    if settings.client.read_local_logs {
        print_local_log(task.id, style, settings, lines);
    } else if let Some(output) = &task_log.output {
        print_remote_log(output, task_log.output_complete, style, lines);
    } else {
        println!("Logs requested from pueue daemon, but none received. Please report this bug.");
    }
    true
}

pub fn task_status_text(task: &Task) -> (String, Color) {
    match &task.status {
        TaskStatus::Paused { .. } => ("paused".to_string(), Color::White),
        TaskStatus::Running { .. } => ("running".to_string(), Color::Yellow),
        TaskStatus::Done { result, .. } => match result {
            TaskResult::Success => ("completed successfully".to_string(), Color::Green),
            TaskResult::Failed(code) => (format!("failed with exit code {code}"), Color::Red),
            TaskResult::FailedToSpawn(_) => ("Failed to spawn".to_string(), Color::Red),
            TaskResult::Killed => ("killed by system or user".to_string(), Color::Red),
            TaskResult::Errored => ("some IO error.\n Check daemon log.".to_string(), Color::Red),
            TaskResult::DependencyFailed => ("dependency failed".to_string(), Color::Red),
        },
        TaskStatus::Queued { .. } => ("queued".to_string(), Color::White),
        TaskStatus::Stashed { .. } => ("stashed".to_string(), Color::White),
        TaskStatus::Locked { .. } => ("locked".to_string(), Color::White),
    }
}

/// Render a table with a border, but no inner lines.
fn render_bordered(cells: &[(String, Option<Color>, bool)], style: &OutputStyle) -> String {
    use unicode_width::UnicodeWidthStr;
    let columns: Vec<Vec<&str>> = cells.iter().map(|(text, _, _)| text.split('\n').collect()).collect();
    let widths: Vec<usize> = columns
        .iter()
        .map(|lines| lines.iter().map(|l| l.width()).max().unwrap_or(0))
        .collect();
    let height = columns.iter().map(|c| c.len()).max().unwrap_or(1);
    let inner: usize = widths.iter().map(|w| w + 2).sum::<usize>() + widths.len().saturating_sub(1);

    let mut out = String::new();
    out.push('┌');
    out.push_str(&"─".repeat(inner));
    out.push_str("┐\n");
    for line_index in 0..height {
        out.push('│');
        let mut parts = Vec::new();
        for (index, lines) in columns.iter().enumerate() {
            let content = lines.get(line_index).copied().unwrap_or("");
            let mut text = format!(" {}{} ", content, " ".repeat(widths[index] - content.width()));
            if style.enabled && line_index < lines.len() {
                let (_, color, bold) = &cells[index];
                if *bold {
                    text = format!("\x1b[1m{text}\x1b[0m");
                } else if let Some(color) = color {
                    let color = style.map_color(*color);
                    text = format!("\x1b[38;5;{}m{}\x1b[39m", color.ansi_value(), text);
                }
            }
            parts.push(text);
        }
        out.push_str(&parts.join(" "));
        out.push_str("│\n");
    }
    out.push('└');
    out.push_str(&"─".repeat(inner));
    out.push('┘');
    out
}

pub fn print_task_info(task: &Task, style: &OutputStyle) {
    let (status, color) = task_status_text(task);
    let header = render_bordered(
        &[
            (format!("Task {}: ", task.id), None, true),
