//! The `follow` command.

use std::io::{Read, Write};
use std::time::Duration;

use super::log::{get_log_file_handle, log_file_path, seek_to_last_lines};
use super::{get_state, get_task, location};
use crate::errors::{Report, Result};
use crate::messages::{Request, Response, StreamRequest, TaskSelection, TaskStatus};
use crate::network::Client;
use crate::settings::Settings;
use crate::style::{Color, OutputStyle};

const FOLLOW_RS: &str = "follow.rs";

pub fn follow(
    client: &mut Client,
    settings: &Settings,
    style: &OutputStyle,
    task_id: Option<usize>,
    lines: Option<usize>,
) -> Result<i32> {
    if !settings.client.read_local_logs {
        return follow_remote(client, style, task_id, lines);
    }

    let task_id = match task_id {
        Some(task_id) => task_id,
        None => {
            let state = get_state(client)?;
            let running: Vec<usize> = state
                .tasks
                .values()
                .filter(|task| matches!(task.status, TaskStatus::Running { .. } | TaskStatus::Paused { .. }))
                .map(|task| task.id)
                .collect();
            match running.len() {
                0 => {
                    return Err(Report::new(
                        "There are no running tasks.",
                        &location(FOLLOW_RS),
                        114,
                    ))
                }
                1 => running[0],
                _ => {
                    let ids = running
                        .iter()
                        .map(|id| id.to_string())
                        .collect::<Vec<_>>()
                        .join(", ");
                    return Err(Report::new(
                        format!("Multiple tasks are running, please select one of the following: {ids}"),
                        &location(FOLLOW_RS),
                        123,
                    ));
                }
            }
        }
    };

    follow_local_task_logs(client, settings, task_id, lines)
}

fn follow_local_task_logs(
    client: &mut Client,
    settings: &Settings,
    task_id: usize,
    lines: Option<usize>,
) -> Result<i32> {
    // Wait until the task has been started.
    loop {
        let Some(task) = get_task(client, task_id)? else {
            eprintln!("Pueue: The task to be followed doesn't exist.");
            return Ok(1);
        };
        if matches!(
            task.status,
            TaskStatus::Running { .. } | TaskStatus::Paused { .. } | TaskStatus::Done { .. }
        ) {
            break;
        }
        std::thread::sleep(Duration::from_millis(1000));
    }

    let pueue_directory = settings.shared.pueue_directory();
    let mut handle = match get_log_file_handle(task_id, &pueue_directory) {
        Ok(handle) => handle,
        Err(err) => {
            eprintln!("Failed to get log file handles: {err}");
            return Ok(0);
        }
    };
    let path = log_file_path(&pueue_directory, task_id);

    if let Some(lines) = lines {
        if let Err(err) = seek_to_last_lines(&mut handle, lines) {
            eprintln!("Error seeking to last lines from log: {err}");
        }
    }

    let log_check_interval = 250;
    let task_check_interval = log_check_interval * 2;
    let mut last_check = 0;
    let mut buffer = vec![0u8; 8192];
    loop {
        if !path.exists() {
            eprintln!("Pueue: Log file has gone away. Has the task been removed?");
            return Ok(0);
        }

        {
            let mut stdout = std::io::stdout().lock();
            loop {
                match handle.read(&mut buffer) {
                    Ok(0) => break,
                    Ok(n) => {
                        if let Err(err) = stdout.write_all(&buffer[..n]) {
                            eprintln!("Pueue: Error while reading file: {err}");
                            return Ok(0);
                        }
                    }
                    Err(err) => {
                        eprintln!("Pueue: Error while reading file: {err}");
                        return Ok(0);
                    }
                }
            }
            if let Err(err) = stdout.flush() {
                eprintln!("Pueue: Error while flushing stdout: {err}");
                return Ok(0);
            }
        }

        if last_check % task_check_interval == 0 {
            let Some(task) = get_task(client, task_id)? else {
                eprintln!("Pueue: The followed task has been removed.");
                return Ok(1);
            };
            if !matches!(task.status, TaskStatus::Running { .. } | TaskStatus::Paused { .. }) {
                return Ok(0);
            }
        }

        last_check += log_check_interval;
        std::thread::sleep(Duration::from_millis(log_check_interval as u64));
    }
}

fn follow_remote(
    client: &mut Client,
    style: &OutputStyle,
    task_id: Option<usize>,
    lines: Option<usize>,
) -> Result<i32> {
    let task_ids = task_id.map(|id| vec![id]).unwrap_or_default();
    let request = Request::Stream(StreamRequest {
        tasks: TaskSelection::TaskIds(task_ids),
        lines,
    });
    client
        .send_request(&request)
        .map_err(|err| err.report(&location(FOLLOW_RS), 59))?;

    loop {
        let response = client
            .receive_response::<Response>()
            .map_err(|err| err.report(&location(FOLLOW_RS), 66))?;
        match response {
            Response::Stream(stream) => {
                let mut stdout = std::io::stdout().lock();
                for text in stream.logs.values() {
                    let _ = stdout.write_all(text.as_bytes());
                }
                let _ = stdout.flush();
            }
            Response::Close => return Ok(0),
            Response::Failure(text) => {
                eprintln!("{}", style.style_text(text, Some(Color::Red), None));
                return Ok(1);
            }
            other => {
                crate::log::write(
                    crate::log::Level::Error,
                    "pueue::client::commands::follow",
                    &format!("Received unhandled response message: {other:?}"),
                    &[],
                );
            }
        }
    }
}
