//! The `wait` command.

use std::collections::HashMap;
use std::time::Duration;

use chrono::Local;

use super::{get_state, selection};
use crate::errors::Result;
use crate::messages::{Task, TaskResult, TaskSelection, TaskStatus};
use crate::network::Client;
use crate::signal::WaitTargetStatus;
use crate::style::{Attribute, Color, OutputStyle};

fn status_name(status: &TaskStatus) -> &'static str {
    match status {
        TaskStatus::Locked { .. } => "Locked",
        TaskStatus::Stashed { .. } => "Stashed",
        TaskStatus::Queued { .. } => "Queued",
        TaskStatus::Running { .. } => "Running",
        TaskStatus::Paused { .. } => "Paused",
        TaskStatus::Done { .. } => "Done",
    }
}

fn color_for_status(status: &TaskStatus) -> Color {
    match status {
        TaskStatus::Running { .. } => Color::Green,
        TaskStatus::Done { result, .. } => {
            if matches!(result, TaskResult::Success) {
                Color::Green
            } else {
                Color::Red
            }
        }
        _ => Color::White,
    }
}

fn reached_target(task: &Task, target: WaitTargetStatus) -> bool {
    match target {
        WaitTargetStatus::Queued => !matches!(
            task.status,
            TaskStatus::Stashed { .. } | TaskStatus::Locked { .. }
        ),
        WaitTargetStatus::Running => matches!(
            task.status,
            TaskStatus::Running { .. } | TaskStatus::Done { .. }
        ),
        WaitTargetStatus::Done => matches!(task.status, TaskStatus::Done { .. }),
        WaitTargetStatus::Success => matches!(
            task.status,
            TaskStatus::Done {
                result: TaskResult::Success,
                ..
            }
        ),
    }
}

pub fn wait(
    client: &mut Client,
    style: &OutputStyle,
    task_ids: Vec<usize>,
    group: Option<String>,
    all: bool,
    quiet: bool,
    status: Option<WaitTargetStatus>,
) -> Result<i32> {
    let target = status.unwrap_or(WaitTargetStatus::Done);
    let selection = selection(task_ids, group, all);
    let mut first_run = true;
    let mut watched: HashMap<usize, TaskStatus> = HashMap::new();

    loop {
        let state = get_state(client)?;
        let tasks: Vec<Task> = state
            .tasks
            .into_values()
            .filter(|task| match &selection {
                TaskSelection::TaskIds(ids) => ids.contains(&task.id),
                TaskSelection::Group(group) => &task.group == group,
                TaskSelection::All => true,
            })
            .collect();

        if tasks.is_empty() {
            eprintln!("No tasks found for selection {selection:?}");
            return Ok(0);
        }

        let current_time = Local::now().format("%H:%M:%S").to_string();

        for task in &tasks {
            let previous = match watched.get(&task.id) {
                None => {
                    if !quiet {
                        let color = color_for_status(&task.status);
                        let task_id = style.style_text(task.id, None, Some(Attribute::Bold));
                        let status = style.style_text(status_name(&task.status), Some(color), None);
                        if !first_run {
                            println!("{current_time} - New task {task_id} with status {status}");
                        } else if matches!(
                            task.status,
                            TaskStatus::Running { .. } | TaskStatus::Paused { .. }
                        ) {
                            println!("{current_time} - Found active Task {task_id} with status {status}");
                        }
                    }
                    watched.insert(task.id, task.status.clone());
                    continue;
                }
                Some(previous) => {
                    if previous == &task.status {
                        continue;
                    }
                    previous.clone()
                }
            };

            watched.insert(task.id, task.status.clone());
            if !quiet {
                log_status_change(&current_time, &previous, task, style);
            }
        }

        if target == WaitTargetStatus::Success && tasks.iter().any(|task| task.failed()) {
            return Ok(1);
        }

        if tasks.iter().all(|task| reached_target(task, target)) {
            break;
        }

        first_run = false;
        std::thread::sleep(Duration::from_millis(2000));
    }

    Ok(0)
}

fn log_status_change(current_time: &str, previous: &TaskStatus, task: &Task, style: &OutputStyle) {
    let task_id = style.style_text(task.id, None, Some(Attribute::Bold));
    if let TaskStatus::Done { result, .. } = &task.status {
        let text = match result {
            TaskResult::Success => format!(
                "Task {task_id} succeeded with {}",
                style.style_text("0", Some(Color::Green), None)
            ),
            TaskResult::DependencyFailed => format!(
                "Task {task_id} failed due to {}",
                style.style_text("failed dependencies", Some(Color::Red), None)
            ),
            TaskResult::FailedToSpawn(_) => format!(
                "Task {task_id} {}",
                style.style_text("failed to spawn", Some(Color::Red), None)
            ),
            TaskResult::Failed(code) => format!(
                "Task {task_id} failed with {}",
                style.style_text(code, Some(Color::Red), Some(Attribute::Bold))
            ),
            TaskResult::Killed => format!(
                "Task {task_id} has been {}",
                style.style_text("killed", Some(Color::Red), None)
            ),
            TaskResult::Errored => format!(
                "Task {task_id} experienced an {}.",
                style.style_text("IO error", Some(Color::Red), Some(Attribute::Bold))
            ),
        };
        println!("{current_time} - {text}");
        return;
    }

    println!(
        "{current_time} - Task {task_id} changed from {} to {}",
        style.style_text(status_name(previous), Some(color_for_status(previous)), None),
        style.style_text(status_name(&task.status), Some(color_for_status(&task.status)), None)
    );
}
