//! The `restart` command.

use super::{get_state, location, send_and_receive, SubCommand};
use crate::errors::{Report, Result};
use crate::messages::{AddRequest, Request, RestartRequest, Response, Task, TaskStatus, TaskToRestart};
use crate::network::Client;
use crate::settings::Settings;
use crate::style::OutputStyle;

const RESTART_RS: &str = "restart.rs";

pub fn restart(
    client: &mut Client,
    settings: &Settings,
    style: &OutputStyle,
    subcommand: SubCommand,
) -> Result<i32> {
    let SubCommand::Restart {
        task_ids,
        all_failed,
        failed_in_group,
        start_immediately,
        stashed,
        in_place,
        not_in_place,
        edit,
    } = subcommand
    else {
        unreachable!()
    };

    let in_place = (settings.client.restart_in_place || in_place) && !not_in_place;

    let state = get_state(client)?;

    let selected: Vec<usize> = if all_failed {
        state
            .tasks
            .values()
            .filter(|task| task.failed())
            .map(|task| task.id)
            .collect()
    } else if let Some(group) = &failed_in_group {
        state
            .tasks
            .values()
            .filter(|task| &task.group == group && task.failed())
            .map(|task| task.id)
            .collect()
    } else {
        if task_ids.is_empty() {
            return Err(Report::new(
                "Please provide the ids of the tasks you want to restart.",
                &location(RESTART_RS),
                89,
            ));
        }
        task_ids
    };

    let mut restartable: Vec<Task> = Vec::new();
    let mut failed: Vec<usize> = Vec::new();
    for id in selected {
        match state.tasks.get(&id) {
            Some(task) if matches!(task.status, TaskStatus::Done { .. }) => restartable.push(task.clone()),
            _ => failed.push(id),
        }
    }

    let mut to_restart: Vec<TaskToRestart> = restartable
        .iter()
        .map(|task| TaskToRestart {
            task_id: task.id,
            original_command: task.original_command.clone(),
            path: task.path.clone(),
            label: task.label.clone(),
            priority: task.priority,
        })
        .collect();

    if edit {
        to_restart = super::edit::edit_tasks_for_restart(settings, to_restart)?;
    }

    if in_place {
        let request = Request::Restart(RestartRequest {
            tasks: to_restart.clone(),
            start_immediately,
            stashed,
        });
        let response = send_and_receive(client, request, RESTART_RS, 169)?;
        if let Response::Failure(text) = response {
            return Err(Report::new(text, &location(RESTART_RS), 170));
        }
    } else {
        for (task, edited) in restartable.iter().zip(to_restart.iter()) {
            let request = Request::Add(AddRequest {
                command: edited.original_command.clone(),
                path: edited.path.clone(),
                envs: task.envs.clone(),
                start_immediately,
                stashed,
                group: task.group.clone(),
                enqueue_at: None,
                dependencies: Vec::new(),
                priority: Some(edited.priority),
                label: edited.label.clone(),
            });
            let response = send_and_receive(client, request, RESTART_RS, 161)?;
            if let Response::Failure(text) = response {
                return Err(Report::new(text, &location(RESTART_RS), 162));
            }
        }
    }

    let _ = style;
    if !restartable.is_empty() {
        let ids: Vec<usize> = restartable.iter().map(|task| task.id).collect();
        println!("Restarted tasks: {ids:?}");
    }
    if !failed.is_empty() {
        eprintln!("Couldn't restart tasks: {failed:?}");
    }

    Ok(0)
}
