//! The `edit` command.

use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

use super::{handle_response, location, send_and_receive};
use crate::errors::{Report, Result};
use crate::messages::{EditableTask, Request, Response, TaskToRestart};
use crate::network::Client;
use crate::settings::{EditMode, Settings};
use crate::style::OutputStyle;

const EDIT_RS: &str = "pueue/src/client/commands/edit.rs";

fn report(msg: impl Into<String>, line: u32) -> Report {
    Report::new(msg, EDIT_RS, line)
}

pub fn edit(
    client: &mut Client,
    settings: &Settings,
    style: &OutputStyle,
    task_ids: Vec<usize>,
) -> Result<i32> {
    let response = send_and_receive(client, Request::EditRequest(task_ids.clone()), "edit.rs", 34)?;
    let Response::Edit(editable_tasks) = response else {
        return Ok(handle_response(style, response));
    };

    let edited = match edit_tasks(settings, editable_tasks) {
        Ok(tasks) => tasks,
        Err(report) => {
            eprintln!("Encountered an error while editing. Trying to restore the task's status.");
            let ids = task_ids.clone();
            let response = send_and_receive(client, Request::EditRestore(ids), "edit.rs", 51)?;
            match response {
                Response::Success(text) => eprintln!("{text}"),
                Response::Failure(text) => eprintln!("{text}"),
                _ => {}
            }
            return Err(report);
        }
    };

    let response = send_and_receive(client, Request::EditedTasks(edited), "edit.rs", 62)?;
    Ok(handle_response(style, response))
}

/// Edit the restart candidates in the editor.
pub fn edit_tasks_for_restart(
    settings: &Settings,
    tasks: Vec<TaskToRestart>,
) -> Result<Vec<TaskToRestart>> {
    let editable: Vec<EditableTask> = tasks
        .iter()
        .map(|task| EditableTask {
            id: task.task_id,
            original_command: task.original_command.clone(),
            path: task.path.clone(),
            label: task.label.clone(),
            priority: task.priority,
        })
        .collect();
    let edited = edit_tasks(settings, editable)?;
    Ok(edited
        .into_iter()
        .map(|task| TaskToRestart {
            task_id: task.id,
            original_command: task.original_command,
            path: task.path,
            label: task.label,
            priority: task.priority,
        })
        .collect())
}

fn create_temp_dir() -> std::io::Result<PathBuf> {
    use std::time::{SystemTime, UNIX_EPOCH};
    let chars: Vec<char> = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789"
        .chars()
        .collect();
    let mut seed = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|d| d.as_nanos() as u64)
        .unwrap_or(0)
        ^ (std::process::id() as u64).rotate_left(32);
    for _ in 0..100 {
        let mut name = String::from(".tmp");
        for _ in 0..6 {
            seed ^= seed << 13;
            seed ^= seed >> 7;
            seed ^= seed << 17;
            name.push(chars[(seed % chars.len() as u64) as usize]);
        }
        let path = std::env::temp_dir().join(name);
        match std::fs::create_dir(&path) {
            Ok(()) => return Ok(path),
            Err(err) if err.kind() == std::io::ErrorKind::AlreadyExists => continue,
            Err(err) => return Err(err),
        }
    }
    Err(std::io::Error::other("failed to create temporary directory"))
}

pub fn edit_tasks(settings: &Settings, tasks: Vec<EditableTask>) -> Result<Vec<EditableTask>> {
    let dir = create_temp_dir().map_err(|err| {
        report(format!("Failed to create temporary directory:\n{err}"), 110)
    })?;
    let result = match settings.client.edit_mode {
        EditMode::Toml => edit_toml(&dir, tasks),
        EditMode::Files => edit_files(&dir, tasks),
    };
    let _ = std::fs::remove_dir_all(&dir);
    result
}

fn run_editor(path: &Path) -> Result<()> {
    let Ok(editor) = std::env::var("EDITOR") else {
        return Err(report(
            "The '$EDITOR' environment variable couldn't be read. Aborting.",
            170,
        ));
    };
    let command = format!("{editor} {}", path.to_string_lossy());
    let status = std::process::Command::new("sh")
        .arg("-c")
        .arg(&command)
        .env("PUEUE_EDIT_PATH", path)
        .status();
    match status {
        Ok(status) if status.success() => Ok(()),
        Ok(_) => Err(report("The editor exited with a non-zero code. Aborting.", 188)),
        Err(err) => Err(report(format!("Failed to start editor:\n{err}"), 182)),
    }
}

fn edit_toml(dir: &Path, tasks: Vec<EditableTask>) -> Result<Vec<EditableTask>> {
    let path = dir.join("tasks.toml");
    let map: BTreeMap<String, EditableTask> =
        tasks.into_iter().map(|task| (task.id.to_string(), task)).collect();
    let content = toml::to_string(&map).map_err(|err| {
        report(
            format!("Some error occurred. \nFailed to serialize tasks to toml:\n{err}"),
            120,
        )
    })?;
    std::fs::write(&path, content).map_err(|err| {
        report(
            format!("I/O error at path {path:?} while writing temporary file:\n{err}"),
            124,
        )
    })?;

    run_editor(&path)?;

    let content = std::fs::read_to_string(&path).map_err(|err| {
        report(
            format!("I/O error at path {path:?} while reading temporary file:\n{err}"),
            133,
        )
    })?;
    let map: BTreeMap<String, EditableTask> = toml::from_str(&content).map_err(|err| {
        report(
            format!("Some error occurred. \nFailed to deserialize tasks to toml:\n{err}"),
            135,
        )
    })?;
    Ok(sort_by_id(map.into_values().collect()))
}

fn sort_by_id(mut tasks: Vec<EditableTask>) -> Vec<EditableTask> {
    tasks.sort_by_key(|task| task.id);
    tasks
}

fn edit_files(dir: &Path, tasks: Vec<EditableTask>) -> Result<Vec<EditableTask>> {
    for task in &tasks {
        let task_dir = dir.join(task.id.to_string());
        let write = |name: &str, content: &str| -> Result<()> {
            let path = task_dir.join(name);
            std::fs::write(&path, content).map_err(|err| {
                report(
                    format!("I/O error at path {path:?} while writing {name} file:\n{err}"),
                    220,
                )
            })
        };
        std::fs::create_dir_all(&task_dir).map_err(|err| {
            report(
                format!("I/O error at path {task_dir:?} while creating task directory:\n{err}"),
                215,
            )
        })?;
        write("command", &task.original_command)?;
        write("path", &task.path.to_string_lossy())?;
        write("label", task.label.as_deref().unwrap_or(""))?;
        write("priority", &task.priority.to_string())?;
    }

    run_editor(dir)?;

    let mut edited = Vec::new();
    for task in tasks {
        let task_dir = dir.join(task.id.to_string());
        let read = |name: &str, line: u32| -> Result<String> {
            let path = task_dir.join(name);
            std::fs::read_to_string(&path)
                .map(|content| content.trim().to_string())
                .map_err(|err| {
                    report(
                        format!("I/O error at path {path:?} while reading {name} file:\n{err}"),
                        line,
                    )
                })
        };
        let command = read("command", 253)?;
        let path = read("path", 263)?;
        let label = read("label", 283)?;
        let priority = read("priority", 293)?;
        let priority: i32 = priority.parse().map_err(|err: std::num::ParseIntError| {
            report(err.to_string(), 297).wrap(format!(
                "Failed to parse priority string '{priority}' into an integer for task {}",
                task.id
            ))
        })?;
        edited.push(EditableTask {
            id: task.id,
            original_command: command,
            path: PathBuf::from(path),
            label: if label.is_empty() { None } else { Some(label) },
            priority,
        });
    }
    Ok(edited)
}
