//! Status query parsing and application.

use std::cmp::Ordering;

use chrono::{DateTime, Local, NaiveDate, NaiveDateTime, NaiveTime, TimeZone};
use pest::iterators::Pair;
use pest::Parser;
use pest_derive::Parser;

use crate::errors::{Report, Result};
use crate::messages::{Task, TaskResult, TaskStatus};

#[derive(Parser)]
#[grammar = "commands/syntax.pest"]
struct QueryParser;

const QUERY_DIR: &str = "pueue/src/client/commands/state/query";

fn location(file: &str) -> String {
    format!("{QUERY_DIR}/{file}")
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Column {
    Id,
    Status,
    Priority,
    EnqueueAt,
    Dependencies,
    Label,
    Command,
    Path,
    Start,
    End,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Op {
    Eq,
    Neq,
    Lt,
    Gt,
    Contains,
}

#[derive(Clone, Copy, Debug)]
enum StatusValue {
    Queued,
    Stashed,
    Paused,
    Running,
    Success,
    Failed,
}

#[derive(Clone, Debug)]
enum TimeValue {
    DateTime(DateTime<Local>),
    Date(NaiveDate),
}

#[derive(Clone, Copy, Debug)]
enum TimeColumn {
    Start,
    End,
    EnqueueAt,
}

#[derive(Clone, Debug)]
enum Filter {
    Status(Op, StatusValue),
    Command(Op, String),
    Label(Op, String),
    Time(TimeColumn, Op, TimeValue),
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Limit {
    First(usize),
    Last(usize),
}

#[derive(Default)]
pub struct QueryResult {
    pub columns: Vec<Column>,
    filters: Vec<Filter>,
    order_by: Option<(Column, bool)>,
    limit: Option<Limit>,
}

fn column_from_rule(rule: Rule) -> Column {
    match rule {
        Rule::column_id => Column::Id,
        Rule::column_status => Column::Status,
        Rule::column_command => Column::Command,
        Rule::column_label => Column::Label,
        Rule::column_path => Column::Path,
        Rule::column_enqueue_at => Column::EnqueueAt,
        Rule::column_dependencies => Column::Dependencies,
        Rule::column_start => Column::Start,
        _ => Column::End,
    }
}

fn op_from_rule(rule: Rule) -> Op {
    match rule {
        Rule::eq => Op::Eq,
        Rule::neq => Op::Neq,
        Rule::lt => Op::Lt,
        Rule::gt => Op::Gt,
        _ => Op::Contains,
    }
}

fn column_of(pair: Pair<Rule>) -> Column {
    // A `column` pair contains exactly one specific column.
    let inner = pair.into_inner().next();
    match inner {
        Some(inner) => column_from_rule(inner.as_rule()),
        None => Column::Id,
    }
}

pub fn apply_query(query: &str) -> Result<QueryResult> {
    let mut result = QueryResult::default();
    if query.is_empty() {
        return Ok(result);
    }

    let mut parsed = QueryParser::parse(Rule::query, query).map_err(|err| {
        Report::new(err.to_string(), &location("mod.rs"), 163).wrap("Failed to parse query")
    })?;

    let Some(query_pair) = parsed.next() else {
        return Ok(result);
    };

    for section in query_pair.into_inner() {
        match section.as_rule() {
            Rule::column_selection => {
                for inner in section.into_inner() {
                    if inner.as_rule() == Rule::multiple_columns {
                        for column in inner.into_inner() {
                            result.columns.push(column_of(column));
                        }
                    }
                }
            }
            Rule::column_status_filter => {
                let mut op = Op::Eq;
                let mut value = StatusValue::Queued;
                for inner in section.into_inner() {
                    match inner.as_rule() {
                        Rule::eq | Rule::neq => op = op_from_rule(inner.as_rule()),
                        Rule::status_queued => value = StatusValue::Queued,
                        Rule::status_stashed => value = StatusValue::Stashed,
                        Rule::status_paused => value = StatusValue::Paused,
                        Rule::status_running => value = StatusValue::Running,
                        Rule::status_success => value = StatusValue::Success,
                        Rule::status_failed => value = StatusValue::Failed,
                        _ => {}
                    }
                }
                result.filters.push(Filter::Status(op, value));
            }
            Rule::column_command_filter | Rule::column_label_filter => {
                let is_command = section.as_rule() == Rule::column_command_filter;
                let mut op = Op::Eq;
                let mut value = String::new();
                for inner in section.into_inner() {
                    match inner.as_rule() {
                        Rule::eq | Rule::neq | Rule::contains => op = op_from_rule(inner.as_rule()),
                        Rule::filter_value => value = inner.as_str().to_string(),
                        _ => {}
                    }
                }
                if is_command {
                    result.filters.push(Filter::Command(op, value));
                } else {
                    result.filters.push(Filter::Label(op, value));
                }
            }
            Rule::datetime_filter => {
                let mut column = TimeColumn::Start;
                let mut op = Op::Eq;
                let mut value: Option<TimeValue> = None;
                for inner in section.into_inner() {
                    match inner.as_rule() {
                        Rule::column_start => column = TimeColumn::Start,
                        Rule::column_end => column = TimeColumn::End,
                        Rule::column_enqueue_at => column = TimeColumn::EnqueueAt,
                        Rule::eq | Rule::neq | Rule::lt | Rule::gt => op = op_from_rule(inner.as_rule()),
                        Rule::time => {
                            let time = NaiveTime::parse_from_str(inner.as_str(), "%H:%M:%S")
                                .map_err(|err| {
                                    Report::new(err.to_string(), &location("filters.rs"), 86)
                                        .wrap("Expected hh:mm:ss time format")
                                })?;
                            let today = Local::now().date_naive();
                            let datetime = Local
                                .from_local_datetime(&today.and_time(time))
                                .earliest()
                                .unwrap_or_else(Local::now);
                            value = Some(TimeValue::DateTime(datetime));
                        }
                        Rule::datetime => {
                            let datetime =
                                NaiveDateTime::parse_from_str(inner.as_str(), "%Y-%m-%d %H:%M:%S")
                                    .map_err(|err| {
                                        Report::new(err.to_string(), &location("filters.rs"), 93)
                                            .wrap("Expected YYYY-MM-SS hh:mm:ss date time format")
                                    })?;
                            let datetime = Local
                                .from_local_datetime(&datetime)
                                .earliest()
                                .unwrap_or_else(Local::now);
                            value = Some(TimeValue::DateTime(datetime));
                        }
                        Rule::date => {
                            let date = NaiveDate::parse_from_str(inner.as_str(), "%Y-%m-%d")
                                .map_err(|err| {
                                    Report::new(err.to_string(), &location("filters.rs"), 98)
                                        .wrap("Expected YYYY-MM-SS date format")
                                })?;
                            value = Some(TimeValue::Date(date));
                        }
                        _ => {}
                    }
                }
                if let Some(value) = value {
                    result.filters.push(Filter::Time(column, op, value));
                }
            }
            Rule::order_by => {
                let mut column = Column::Id;
                let mut descending = false;
                for inner in section.into_inner() {
                    match inner.as_rule() {
                        Rule::column => column = column_of(inner),
                        Rule::descending => descending = true,
                        Rule::ascending => descending = false,
                        _ => {}
                    }
                }
                result.order_by = Some((column, descending));
            }
            Rule::limit_condition => {
                let mut first = true;
                let mut count = String::new();
                for inner in section.into_inner() {
                    match inner.as_rule() {
                        Rule::first => first = true,
                        Rule::last => first = false,
                        Rule::limit_count => count = inner.as_str().to_string(),
                        _ => {}
                    }
                }
                let count: usize = count.parse().map_err(|err: std::num::ParseIntError| {
                    Report::new(err.to_string(), &location("limit.rs"), 62)
                        .wrap("Expected a number 0 for limit condition")
                })?;
                if count == 0 {
                    return Err(Report::new(
                        "Expected a number >0 for limit condition",
                        &location("limit.rs"),
                        65,
                    ));
                }
                result.limit = Some(if first {
                    Limit::First(count)
                } else {
                    Limit::Last(count)
                });
            }
            _ => {}
        }
    }

    Ok(result)
}

fn status_matches(task: &Task, value: StatusValue) -> bool {
    match value {
        StatusValue::Queued => matches!(task.status, TaskStatus::Queued { .. }),
        StatusValue::Stashed => matches!(task.status, TaskStatus::Stashed { .. }),
        StatusValue::Paused => matches!(task.status, TaskStatus::Paused { .. }),
        StatusValue::Running => matches!(task.status, TaskStatus::Running { .. }),
        StatusValue::Success => matches!(
            task.status,
            TaskStatus::Done {
                result: TaskResult::Success,
                ..
            }
        ),
        StatusValue::Failed => task.failed(),
    }
}

fn compare<T: PartialOrd + PartialEq>(field: &T, op: Op, value: &T) -> bool {
    match op {
        Op::Eq => field == value,
        Op::Neq => field != value,
        Op::Lt => field < value,
        Op::Gt => field > value,
        Op::Contains => false,
    }
}

fn filter_matches(task: &Task, filter: &Filter) -> bool {
    match filter {
        Filter::Status(op, value) => {
            let matched = status_matches(task, *value);
            if *op == Op::Neq {
                !matched
            } else {
                matched
            }
        }
        Filter::Command(op, value) => match op {
            Op::Eq => &task.command == value,
            Op::Neq => &task.command != value,
            Op::Contains => task.command.contains(value.as_str()),
            _ => false,
        },
        Filter::Label(op, value) => match op {
            Op::Eq => task.label.as_deref() == Some(value.as_str()),
            Op::Neq => task.label.as_deref() != Some(value.as_str()),
            Op::Contains => task
                .label
                .as_ref()
                .map(|label| label.contains(value.as_str()))
                .unwrap_or(false),
            _ => false,
        },
