old=s[s.index('/// Render a table with a border, but no inner lines.'):s.index('pub fn print_task_info(')]
new='''/// Render a table with a border, but no inner lines.
fn render_bordered(cells: &[(String, Option<Color>, bool)], style: &OutputStyle) -> String {
    use unicode_width::UnicodeWidthStr;
    let mut columns: Vec<Vec<String>> = cells
        .iter()
        .map(|(text, _, _)| text.split('\\n').map(|l| l.to_string()).collect())
        .collect();
    let mut widths: Vec<usize> = columns
        .iter()
        .map(|lines| lines.iter().map(|l| l.width()).max().unwrap_or(0))
        .collect();

    if let Some(terminal_width) = super::table::terminal_width() {
        let all_cells = vec![columns.clone()];
        widths = super::table::arrange_with_borders(
            terminal_width,
            widths.len() + 1,
            &widths,
            &all_cells,
        );
        for (index, lines) in columns.iter_mut().enumerate() {
            let mut wrapped = Vec::new();
            for line in lines.iter() {
                if line.width() > widths[index] {
                    wrapped.extend(super::table::split_line(line, widths[index]));
                } else {
                    wrapped.push(line.clone());
                }
            }
            *lines = wrapped;
        }
    }

    let height = columns.iter().map(|c| c.len()).max().unwrap_or(1);
